INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('1','中共中央国务院关于完整准确全面贯彻新发展理念做好 碳达峰碳中和工作的意见','综合','其他','全国（000000 QG）',NULL,'国务院令（行政法规）','国务院','2021-09-22','2022-06-20','2021-09-22',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><br></p><p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（</span><span style="font-family:楷体_GB2312">2021年9月22日）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">实现碳达峰、碳中和，是以习近平同志为核心的党中央统筹国内国际两个大局作出的重大战略决策，是着力解决资源环境约束突出问题、实现中华民族永续发展的必然选择，是构建人类命运共同体的庄严承诺。为完整、准确、全面贯彻新发展理念，做好碳达峰、碳中和工作，现提出如下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，深入贯彻习近平生态文明思想，立足新发展阶段，贯彻新发展理念，构建新发展格局，坚持系统观念，处理好发展和减排、整体和局部、短期和中长期的关系，把碳达峰、碳中和纳入经济社会发展全局，以经济社会发展全面绿色转型为引领，以能源绿色低碳发展为关键，加快形成节约资源和保护环境的产业结构、生产方式、生活方式、空间格局，坚定不移走生态优先、绿色低碳的高质量发展道路，确保如期实现碳达峰、碳中和。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）工作原则</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">实现碳达峰、碳中和目标，要坚持</span><span style="font-family:宋体">“全国统筹、节约优先、双轮驱动、内外畅通、防范风险”原则。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——全国统筹。全国一盘棋，强化顶层设计，发挥制度优势，实行党政同责，压实各方责任。根据各地实际分类施策，鼓励主动作为、率先达峰。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——节约优先。把节约能源资源放在首位，实行全面节约战略，持续降低单位产出能源资源消耗和碳排放，提高投入产出效率，倡导简约适度、绿色低碳生活方式，从源头和入口形成有效的碳排放控制阀门。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-si',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('2','中共中央国务院印发《国家创新驱动发展战略纲要》','综合','其他','全国（000000 QG）','中发〔2016〕4号','国务院令（行政法规）','国务院','2016-05-19','2022-06-20','2016-05-19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">党的十八大提出实施创新驱动发展战略，强调科技创新是提高社会生产力和综合国力的战略支撑，必须摆在国家发展全局的核心位置。这是中央在新的发展阶段确立的立足全局、面向全球、聚焦关键、带动整体的国家重大发展战略。为加快实施这一战略，特制定本纲要。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、战略背景</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新驱动就是创新成为引领发展的第一动力，科技创新与制度创新、管理创新、商业模式创新、业态创新和文化创新相结合，推动发展方式向依靠持续的知识积累、技术进步和劳动力素质提升转变，促进经济向形态更高级、分工更精细、结构更合理的阶段演进。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新驱动是国家命运所系。国家力量的核心支撑是科技创新能力。创新强则国运昌，创新弱则国运殆。我国近代落后挨打的重要原因是与历次科技革命失之交臂，导致科技弱、国力弱。实现中华民族伟大复兴的中国梦，必须真正用好科学技术这个最高意义上的革命力量和有力杠杆。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新驱动是世界大势所趋。全球新一轮科技革命、产业变革和军事变革加速演进，科学探索从微观到宇观各个尺度上向纵深拓展，以智能、绿色、泛在为特征的群体性技术革命将引发国际产业分工重大调整，颠覆性技术不断涌现，正在重塑世界竞争格局、改变国家力量对比，创新驱动成为许多国家谋求竞争优势的</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">核心战略。我国既面临赶超跨越的难得历史机遇，也面临差距拉大的严峻挑战。惟有勇立世界科技创新潮头，才能赢得发展主动权，为人类文明进步作出更大贡献。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新驱动是发展形势所迫。我国经济发展进入新常态，传统发展动力不断减弱，粗放型增长方式难以为继。必须依靠创新驱动打造发展新引擎，培育新的经济增长点，持续提升我国经济发展的质量和效益，开辟我国发展的新空间，实现经济保持中高速增长和产业迈向中高端水平</span><span style="font-family:宋体">“双目标”。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">当前，我国创新驱动发展已具备发力加速的基础。经过多年努力，科技发展正在进入由量的增长向质的提升的跃升期，科研体系日益完备，人才队伍不断壮大，科学、技术、工程、产业的自主创新能力快速提升。经济转型升级、民生持续改善和国防现代化建设对创新提出了巨大需求。庞大的市场规模、完备的产业体系、多样化的消费需求与互联网时代创新效率的提升相结合，为创新提供了广阔空间。中国特色社会主义制度能够有效结合集中力量办大事和市场配置资源的优势，为实现创新驱动发展提供了根本保障。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">同时也要看到，我国许多产业仍处于全球价值链的中低端，一些关键核心技术受制于人，发达国家在科学前沿和高技术领域仍然占据明显领先优势，我国支撑产业升级、引领未来发展的科学技术储备亟待加强。适应创新驱动的体制机制亟待建立健全，企业创新动力不足，创新体系整体效能不高，经济发展尚未真正转到依靠创新的轨道。科技人才队伍大而不强，领军人才和高技能人才缺乏，创新型企业家群体亟需发展壮大。激励创新的市场环境和社会氛围仍需进一步培育和优化。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">在我国加快推进社会主义现代化、实现</span><span style="font-family:宋体">“两个一百年”奋斗目标和中华民族伟大复兴中国梦的关键阶段，必须始终坚持抓创新就是抓发展、谋创新就是谋未来，让创新成为国家意志和全社会的共同行动，走出一条从人才强、科技强到产业强、经济强、国家强的发展新路径，为我国未来十几年乃至更长时间创造一个新的增长周期。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、战略要求</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想</span></span></p><p',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('3','国务院办公厅关于积极推进供应链创新与应用的指导意见','综合','其他','全国（000000 QG）','国办发〔2017〕84号','国务院令（行政法规）','国务院办公厅','2017-10-05','2022-06-20','2017-10-05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">供应链是以客户需求为导向，以提高质量和效率为目标，以整合资源为手段，实现产品设计、采购、生产、销售、服务等全过程高效协同的组织形态。随着信息技术的发展，供应链已发展到与互联网、物联网深度融合的智慧供应链新阶段。为加快供应链创新与应用，促进产业组织方式、商业模式和政府治理方式创新，推进供给侧结构性改革，经国务院同意，现提出以下意见。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、重要意义</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）落实新发展理念的重要举措。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">供应链具有创新、协同、共赢、开放、绿色等特征，推进供应链创新发展，有利于加速产业融合、深化社会分工、提高集成创新能力，有利于建立供应链上下游企业合作共赢的协同发展机制，有利于建立覆盖设计、生产、流通、消费、回收等各环节的绿色产业体系。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）供给侧结构性改革的重要抓手。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">供应链通过资源整合和流程优化，促进产业跨界和协同发展，有利于加强从生产到消费等各环节的有效对接，降低企业经营和交易成本，促进供需精准匹配和产业转型升级，全面提高产品和服务质量。供应链金融的规范发展，有利于拓宽中小微企业的融资渠道，确保资金流向实体经济。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）引领全球化提升竞争力的重要载体。</span></span></p><p style="text-indent:32px;text-align:justify;text-justify:distribute-all-lines;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">推进供应链全球布局，加强与伙伴国家和地区之间的合作共赢，有利于我国企业更深更广融入全球供给体系，推进</span><span style="font-family:宋体">“一带一路”建设落地，打造全球利益共同体和命运共同体。建立基于供应链的全球贸易新规则，有利于提高我国在全球</span></span></p><p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">经济治理中的话语权，保障我国资源能源安全和产业安全。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、总体要求</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，认真落实党中央、国务院决策部署，统筹推进</span><span style="font-family:宋体">“五位一体”总体布局和协调推进“四个全面”战略布局，坚持以人民为中心的发展思想，坚持稳中求进工作总基调，牢固树立和贯彻落实创新、协调、绿色、开放、共享的发展理念，以提高发展质量和效益为中心，以供应链与互联网、物联网深度融合为路径，以信息化、标准化、信用体系建设和人才培养为支撑，创新发展供应链新理念、新技术、新模式，高效整合各类资源和要素，提升产业集成和协同水平，打造大数据支撑、网络化共享、智能化协作的智慧供应链体系，推进供给侧结构性改革，提升我国经济全球竞争力。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-fa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('4','国务院办公厅关于县域创新驱动发展的若干意见','综合','其他','全国（000000 QG）','国办发〔2017〕43号','国务院令（行政法规）','国务院办公厅','2017-05-11','2022-06-20','2017-05-11',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">实施创新驱动发展战略，基础在县域，活力在县域，难点也在县域。新形势下，支持县域开展以科技创新为核心的全面创新，推动大众创业、万众创新，加快实现创新驱动发展，是打造发展新引擎、培育发展新动能的重要举措，对于推动县域经济社会协调发展、确保如期实现全面建成小康社会奋斗目标具有重要意义。经过多年努力，我国县域科技创新取得了长足进步，对县域经济社会发展的支撑作用显著增强，但总体仍然比较薄弱，区域发展不平衡等现象突出。为贯彻落实全国科技创新大会精神，全面实施《国家创新驱动发展战略纲要》，推动实现县域创新驱动发展，现提出以下意见。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，按照党中央、国务院决策部署，统筹推进</span><span style="font-family:宋体">“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立和贯彻落实新发展理念，发挥科技创新在县域供给侧结构性改革中的支撑引领作用，强化科技与县域经济社会发展有效对接，打通从科技强、产业强到经济社会发展强的通道。以建设创新型县（市）和创新型乡镇为抓手，深入推动大众创业、万众创新，整合优化县域创新创业资源，构建多层次、多元化县域创新创业格局，推动形成县域创新创业新热潮，以创业带动就业，培育新动能、发展新经济，促进实现县域创新驱动发展。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">——创新驱动。坚持创新是引领发展的第一动力，加强创新资源共享，完善创业培育服务，激发全社会创新创业活力，推动大众创业、万众创新向更大范围、更高层次、更深程度发展，加快形成具有县域特色的创新驱动发展路径。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">——人才为先。坚持把人才作为支撑县域创新发展的第一资源，实施更加积极的创新创业激励和人才吸引政策，优化县域人才环境，加快培育集聚创新创业人才队伍。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">——需求导向。紧扣县域经济社会发展内在需求，提高科技创新供给质量和效率，集聚各类创新资源，促进产学研用结合，加快先进适用科技成果向县域转移转化，做大做强县域特色产业。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">——差异发展。坚持分类指导、精准施策，结合县域经济社会发展水平和定位，因地制宜确定县域创新驱动发展的目标和任务，加快经济发展方式转变和社会转型，推动实现县域差异化、可持续发展。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）主要目标。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">到</span>2020年，',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('5','国务院关于印发2030年前碳达峰行动方案的通知','综合','其他','全国（000000 QG）','国发〔2021〕23号','国务院令（行政法规）','国务院','2021-10-24','2022-06-20','2021-10-24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">现将《</span><span style="font-family:宋体">2030年前碳达峰行动方案》印发给你们，请认真贯彻执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国务院</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2021年10月24日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（本文有删减）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px"><br/></span><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">2030年前碳达峰行动方案</span></span></strong></p><p style="text-indent:32px;text-autospa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('10','科技部等6部门印发《关于扩大高校和科研院所科研相关 自主权的若干意见》的通知','科研机构改革','其他','全国（000000 QG）','国科发政〔2019〕260号','国务院令（行政法规）',' 科技部 教育部 发展改革委 财政部 人力资源社会保障部 中科院','2019-07-30','2022-06-20','2019-07-30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">《关于扩大高校和科研院所科研相关自主权的若干意见》已经</span><span style="font-family:宋体">2019年3月19日中央全面深化改革委员会第七次会议审议通过,现印发给你们，请认真贯彻执行。落实过程中遇到的重要情况和问题，请及时向科技部、教育部报告反映。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">联系电话：科技部</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">010-58881715</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">教育部</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;</span><span style=";font-family:宋体;font-size:16px">&nbsp;<span style="font-family:宋体">010-66096298</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科技部</span> <span style="font-family:宋体">教育部</span> <span style="font-family:宋体">发展改革委</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">财政部</span> <span style="font-family:宋体">人力资源社会保障部</span> <span style="font-family:宋体">中科院</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2019年7月30日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('11','科技部等9部门印发《赋予科研人员职务科技成果所有权或长期使用权试点实施方案》的通知','科研机构改革','其他','全国（000000 QG）','国科发区〔2020〕128号','国务院令（行政法规）','科技部 发展改革委 教育部 工业和信息化部 财政部 人力资源社会保障部 商务部 知识产权局 中科院','2020-05-09','2022-06-20','2020-05-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各有关单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">《赋予科研人员职务科技成果所有权或长期使用权试点实施方案》（以下简称《实施方案》）已经</span><span style="font-family:宋体">2020年2月14日中央全面深化改革委员会第十二次会议审议通过。现将《实施方案》印发给你们，请结合实际认真贯彻执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科技部</span> <span style="font-family:宋体">发展改革委</span> <span style="font-family:宋体">教育部</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">工业和信息化部</span> <span style="font-family:宋体">财政部</span> <span style="font-family:宋体">人力资源社会保障部</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">商务部</span> <span style="font-family:宋体">知识产权局</span> <span style="font-family:宋体">中科院</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2020年5月9日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件主动公开）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">赋予科研人员职务科技成果所有权或长期使用权试点实施方案</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深化科技成果使用权、处置权和收益权改革，进一步激发科研人员创新热情，促进科技成果转化，根据《中华人民共和国科学技术进步法》《中华人民共和国促进科技成果转化法》《中华人民共和国专利法》相关规定，现就开展赋予科研人员职务科技成果所有权或长期使用权试点工作制定本实施方案。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('16','国家自然科学基金委员会 财政部关于进一步完善科学基金项目和资金管理的通知','科技计划管理','其他','全国（000000 QG）','国科金发财〔2019〕31号','国务院令（行政法规）','国家自然科学基金委员会 财政部','2019-03-28','2022-06-21','2019-03-28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各有关单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为全面贯彻落实习近平总书记在两院院士大会重要讲话精神和《中共中央国务院关于全面实施预算绩效管理的意见》《国务院关于优化科研管理提升科研绩效若干措施的通知》《国务院办公厅关于抓好赋予科研机构和人员更大自主权有关文件贯彻落实工作的通知》的要求，充分激发科研人员创新活力，切实减轻科研人员负担，按照明确责任、简化流程的原则，现就国家自然科学基金（以下简称</span><span style="font-family:宋体">“科学基金”）项目和资金管理有关事项通知如下。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">1.</span><span style="font-family:宋体">精简信息填报和材料报送。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">申请国家杰出青年科学基金项目和创新研究群体项目时，不再需要提供学术委员会或专家组推荐意见；在站博士后人员作为申请人申请面上项目、青年科学基金项目和地区科学基金项目时，不再需要提供依托单位承诺函；青年科学基金项目申请书中不再列出参与者。国家自然科学基金委员会（以下简称</span><span style="font-family:宋体">“自然科学基金委”）将进一步完善项目申请相关文本，简化填报内容。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">取消依托单位项目资金年度收支报告编制报送；依托单位决算汇总表无需报送纸质文件；继续扩大项目无纸化申请试点范围。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">2.</span><span style="font-family:宋体">简化项目预算编制要求。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">编制预算时，定额补助式项目只需提供基本测算说明，不需提供明细；成本补偿式项目只需提供必要的测算过程说明。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">3.</span><span style="font-family:宋体">精简项目过程检查。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">面上项目、青年科学基金项目、地区科学基金项目等一般不开展过程检查，仅在必要时进行抽查；对于其他研究目标相对明确、资金体量较大的项目，自然科学基金委按照相关项目管理办法的要求，在实施中期组织同行专家采取会议或者通讯评审方式，对项目进展和资金使用情况等进行一次检查。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">4.</span><span style="font-family:宋体">赋予科研人员更大技术路线决策权。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科学基金的项目负责人，可以在不改变研究或技术指标的前提下，自行决定研究方案或技术路线。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">5.</span><span style="font-family:宋体">赋予科研单位项目经费管理使用自主权</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">。科学基金项目资金直接费用中除设备费外，其他科目预算调剂权全部下放给依托单位。设备费预算一般不予调增，确需调增的需报自然科学基金委审批；设备费调减、设备费内部预算结构调整、拟购置设备明细发生变化的，由依托单位审批，依托单位要切实履行审批职责。依托单位应按照国家有关规定完善管理制度，相关管理制度报自',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('17','关于进一步优化国家重点研发计划项目和资金管理的通知','科技计划管理','其他','全国（000000 QG）','国科发资〔2019〕45号','国务院令（行政法规）','科技部 财政部','2019-01-22','2022-06-21','2019-01-22',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各有关单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为贯彻落实习近平总书记在两院院士大会上的重要讲话精神和《国务院关于优化科研管理提升科研绩效若干措施的通知》（国发〔</span><span style="font-family:Calibri">2018</span><span style="font-family:宋体">〕</span><span style="font-family:Calibri">25</span><span style="font-family:宋体">号）、《中共中央办公厅、国务院办公厅关于进一步加强科研诚信建设的若干意见》《国务院办公厅关于抓好赋予科研机构和人员更大自主权有关文件贯彻落实工作的通知》（国办发〔</span><span style="font-family:Calibri">2018</span><span style="font-family:宋体">〕</span><span style="font-family:Calibri">127</span><span style="font-family:宋体">号）的要求，充分激发科研人员创新活力，切实减轻科研人员负担，现就国家重点研发计划组织实施有关问题补充通知如下。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">1.</span><span style="font-family:宋体">整合精简各类报表。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">系统梳理项目申报、立项、过程管理和综合绩效评价等环节，优化管理流程，整合项目申报书、任务书、年度报告、中期报告、综合绩效自评价报告等材料中的各类报表，按照减量不减质、满足管理基本需求的原则，将现有项目层面填报的表格，整合精简为</span><span style="font-family:Calibri">6</span><span style="font-family:宋体">张；课题层面填报的表格，整合精简为</span><span style="font-family:Calibri">8</span><span style="font-family:宋体">张，实现“一表多用、一表多能”。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">2.</span><span style="font-family:宋体">减少信息填报和材料报送。</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">从项目申报到综合绩效评价各环节，全面推行信息化方式，通过国家科技管理信息系统填报材料。杜绝科研单位基本信息、科研人员基本信息、项目目标和考核指标等各类信息的重复填报，减少联合申报协议、诚信承诺书等材料的重复报送，实现项目全周期</span><span style="font-family:宋体">“信息一次填报、材料一次报送”。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">合并年度报告和预算执行报告，不再单独编报年度财务决算报告；减少纸质材料报送，一般情况下，项目牵头单位报送的纸质材料（除任务书外）不超过</span><span style="font-family:Calibri">2</span><span style="font-family:宋体">套。除共性要求外，项目管理专业机构不得额外增加半年报、季报等材料和表格报送，切实减轻科研人员负担。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">3.</span><span style="font-family:宋体">精简过程检查</span></span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">。按照任务书约定，在关键节点开展里程碑式管理；实施周期三年以下的项目，一般不开展过程检查。项目管理专业机构提前制定年度检查工作方案，相对集中时间开展检查，避免在同一年度对同一项目重复检查、多头检查。同时，注重年度报告等已有信息的分析运用，尽量让科研人员少填报信息。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:Calibri">4.</span><span style="font-family:宋体">赋予科研人员更大',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('30','关于印发《中央引导地方科技发展资金管理办法》的通知','科技经费与财务','其他','全国（000000 QG）','财教〔2019〕129号','国务院令（行政法规）','财政部 科技部','2019-09-24','2022-06-21','2019-09-24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市、计划单列市财政厅（局）、科技厅（委、局），新疆生产建设兵团财政局、科技局：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为规范和加强中央财政对地方转移支付资金管理，提高资金使用效益，根据《中华人民共和国预算法》《国务院办公厅关于印发科技领域中央与地方财政事权和支出责任划分改革方案的通知》等有关法律法规和政策要求，以及财政部转移支付资金等预算管理规定，我们修订了《中央引导地方科技发展资金管理办法》，现印发给你们，请遵照执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">附件：中央引导地方科技发展资金管理办法</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">财政部</span> <span style="font-family:宋体">科技部</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:Calibri">2019</span><span style="font-family:宋体">年</span><span style="font-family:Calibri">9</span><span style="font-family:宋体">月</span><span style="font-family:Calibri">24</span><span style="font-family:宋体">日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong></p><p style="text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">附件：</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">中央引导地方科技发展资金管理办法</span></span></strong></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">第一条</span><span style="font-family:Calibri">&nbsp;</span></span></strong><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为规范中央引导地方科技发展资金（以下称引导资金）管理，提高引导资金使用效益，推进科技创新，根据国家有关规定，制定本办法。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('31','科技部 财政部 发展改革委关于印发《中央财政科技计划（专项、基金等）绩效评估规范（试行）》的通知','科技经费与财务','其他','全国（000000 QG）','国科发监〔2020〕165号','国务院令（行政法规）','科 技 部 财 政 部 发展改革委','2020-06-19','2022-06-21','2020-06-19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国家科技计划（专项、基金等）管理部际联席会议成员单位，各有关单位：</span></span></p><p style="margin-left:0;text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为贯彻落实党的十九届四中全会关于</span><span style="font-family:宋体">“改进科技评价体系”精神和《中共中央办公厅 国务院办公厅印发〈关于深化项目评审、人才评价、机构评估改革的意见〉的通知》要求，指导和规范中央财政科技计划（专项、基金等）绩效评估工作，加强中央财政科技计划管理，提高科技计划的实施效果和财政资金使用效率，科技部、财政部、发展改革委研究制定了《中央财政科技计划（专项、基金等）绩效评估规范（试行）》，现印发给你们，请认真贯彻执行。</span></span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科</span> <span style="font-family:宋体">技</span> <span style="font-family:宋体">部</span></span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">财</span> <span style="font-family:宋体">政</span> <span style="font-family:宋体">部</span></span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">发展改革委</span></span><span style=";font-family:宋体;font-size:16px"><br/></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:Calibri">2</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:Calibri">020</span><span style="font-family:宋体">年</span><span style="font-family:Calibri">6</span><span style="font-family:宋体">月</span><span style="font-family:Calibri">19</span><span style="font-family:宋体">日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">中央财政科技计划（专项、基金等）绩效评估规范（试行）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">　</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">第一章</span> </span></strong><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">总</span></span></strong><strong><span style="font-family: 宋体;font-size:16px">&nbsp;&nbsp;</span></strong><strong><span style="font-family: 宋体;font-size:1',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('33','国务院关于全面加强基础科学研究的若干意见','基础研究','其他','全国（000000 QG）','国发〔2018〕4号','国务院令（行政法规）','国务院','2018-01-19','2022-06-21','2018-01-19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-bottom:0;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">强大的基础科学研究是建设世界科技强国的基石。当前，新一轮科技革命和产业变革蓬勃兴起，科学探索加速演进，学科交叉融合更加紧密，一些基本科学问题孕育重大突破。世界主要发达国家普遍强化基础研究战略部署，全球科技竞争不断向基础研究前移。经过多年发展，我国基础科学研究取得长足进步，整体水平显著提高，国际影响力日益提升，支撑引领经济社会发展的作用不断增强。但与建设世界科技强国的要求相比，我国基础科学研究短板依然突出，数学等基础学科仍是最薄弱的环节，重大原创性成果缺乏，基础研究投入不足、结构不合理，顶尖人才和团队匮乏，评价激励制度亟待完善，企业重视不够，全社会支持基础研究的环境需要进一步优化。为进一步加强基础科学研究，大幅提升原始创新能力，夯实建设创新型国家和世界科技强国的基础，现提出以下意见。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十九大精神，以习近平新时代中国特色社会主义思想为指导，贯彻创新、协调、绿色、开放、共享的新发展理念，按照党中央、国务院决策部署，深入实施科教兴国战略、创新驱动发展战略，充分发挥科学技术作为第一生产力的作用，充分发挥创新作为引领发展第一动力的作用，瞄准世界科技前沿，强化基础研究，深化科技体制改革，促进基础研究与应用研究融通创新发展，着力实现前瞻性基础研究、引领性原创成果重大突破，全面提升创新能力，全面推进创新型国家和世界科技强国建设，为加快建设社会主义现代化强国、实现中华民族伟大复兴的中国梦提供强大支撑。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">遵循科学规律，坚持分类指导。尊重科学研究灵感瞬间性、方式随意性、路径不确定性的特点，营造有利于创新的环境和文化，鼓励科学家自由畅想、大胆假设、认真求证。推动自由探索和目标导向有机结合，自由探索类基础研究聚焦探索未知的科学问题，勇攀科学高峰；目标导向类基础研究紧密结合经济社会发展需求，加强战略领域前瞻部署。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">突出原始创新，促进融通发展。把提升原始创新能力摆在更加突出位置，坚定创新自信，勇于挑战最前沿的科学问题，提出更多原创理论，作出更多原创发现。强化科教融合、军民融合和产学研深度融合，坚持需求牵引，促进基础研究、应用研究与产业化对接融通，推动不同行业和领域创新要素有效对接。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">创新体制机制，增强创新活力。突出以人为导向，深化科研项目和经费管理改革，营造宽松科研环境，使科研人员潜心、长期从事基础研究。完善分类评价机制，调动科学家、科研院所、高校、企业等方面的积极性创造性。创新政府管理方式，引导企业加强基础研究，提升市场竞争力。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('34','科技部 发展改革委 教育部 中科院 自然科学基金委 关于印发《加强“从0到1”基础研究工作方案》的通知','基础研究','其他','全国（000000 QG）','国科发基〔2020〕46号','国务院令（行政法规）','科 技 部  发展改革委  教 育 部 中 科 院  自然科学基金委  ','2020-01-21','2022-06-21','2020-01-21',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局）、发展改革委、教育厅（委、局），新疆生产建设兵团科技局、发展改革委、教育局，国务院有关部门、有关直属机构，各有关单位：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">为深入贯彻落实</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">《国务院关于全面加强基础科学研究的若</span></span><span style=";font-family:宋体;color:rgb(255,255,255);letter-spacing:0;font-size:16px"><span style="font-family:宋体">干</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">意见》</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">（国发〔</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">2018</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">〕</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">4号</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">）</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">，充分发挥基础研究对科技创新的源头供给和引领作用，解决我国基础研究缺少</span><span style="font-family:宋体">“从0到1”原创性成果的问题，</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">科技部、发展改革委、教育部、中科院、自然科学基金委联合制定了《加强</span><span style="font-family:宋体">“从0到1”基础研究工作方案》。现印发给你们，请结合本单位实际认真落实。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">科</span> <span style="font-family:宋体">技</span> <span style="font-family:宋体">部</span> &nbsp;<span style="font-family:宋体">发展改革委</span> &nbsp;<span style="font-family:宋体">教</span> <span style="font-family:宋体">育</span> <span style="font-family:宋体">部</span></span></p',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('35','关于促进首台（套）重大技术装备示范应用的意见','平台基地','其他','全国（000000 QG）','发改产业〔2018〕558号','国务院令（行政法规）','国家发展改革委  科技部 工业和信息化部  司法部 财政部  国资委 国家市场监督管理总局 知识产权局','2018-04-11','2022-06-21','2018-04-11',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院有关部委、直属机构：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">重大技术装备是国之重器，事关综合国力和国家安全。首台（套）重大技术装备（以下简称</span><span style="font-family:宋体">“首台套”）是指国内实现重大技术突破、拥有知识产权、尚未取得市场业绩的装备产品，包括前三台（套）或批（次）成套设备、整机设备及核心部件、控制系统、基础材料、软件系统等。党的十八大以来，在以习近平同志为核心的党中央坚强领导下，我国重大技术装备发展取得了显著成就，有力支撑了经济发展和国防建设，但产业基础薄弱、创新能力不强等问题尚未得到根本解决，首台套示范应用不畅成为装备制造业创新发展的瓶颈制约。为贯彻落实党中央、国务院关于推进供给侧结构性改革、实施创新驱动发展战略、建设制造强国的决策部署，以首台套示范应用为突破口，推动重大技术装备水平整体提升，经国务院同意，现提出以下意见。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十九大精神，坚持以习近平新时代中国特色社会主义思想为指导，紧紧围绕统筹推进</span><span style="font-family:宋体">“五位一体”总体布局和协调推进“四个全面”战略布局，坚持新发展理念，认真落实党中央、国务院决策部署，准确把握科技革命和产业变革新趋势，以推进供给侧结构性改革为主线，着力加强协同创新，着力完善政策体系，着力健全保障机制，着力营造良好环境，推动首台套示范应用取得实质性进展，为装备制造业迈向中高端提供坚实保障。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="text-indent:32px;text-align:justify;text-justify:distribute-all-lines;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">坚持政府引导与市场机制相结合。充分发挥政府部门在顶层设计、公共服</span></span></p><p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">务和制度供给等方面的作用，努力消除信息不对称引发的市场失灵；坚持企业主体地位，尊重市场规律，充分调动各类市场主体参与重大技术装备创新的积极性</span></span><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">坚持政策激励与制度保障相结合。加大政策支持力度，加强科技、产业、财政、金融、保险、军民融合等政策衔接，构建有利于首台套示范应用的政策体系；明确招投标等相关法律法规要求，建立有利于首台套示范应用的保障机制，营造鼓励创新、允许试错、宽容失败的氛围。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">坚持供给提升与需求牵引相结合。提高重大技术装备研发计划的前瞻性和针对性，补齐检验检测和公共服务短板，提升首台套产品供给能力和市场认可度；围绕国家重大战略，深入分析产业发展趋势和市场需求，加强首台套产品供需对接，形成市场需求与研发示范相互促进、良性互动的格局。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">坚持重点突破与协同推进相结合。聚焦国计民生和国家安全重点领域，确定重大技术装备创新发展和首台套示范应用的主攻方向，实施重点突破；充分发挥地方和行业的积极性，因地制宜，分业施策，在优势和特色领域协同推进首台套示范应用，全面提升重大技术装备对经济发展的支撑能力。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）主要目标。</span></span></p><p style="text-indent:32px;line-he',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('36','科技部 财政部关于加强国家重点实验室建设发展的若干意见','平台基地','其他','全国（000000 QG）','国科发基〔2018〕64号','国务院令（行政法规）','科技部    财政部 ','2018-06-22','2022-06-21','2018-06-22',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市、计划单列市科技厅（委、局）、财政厅（局），新疆生产建设兵团科技局、财务局，国务院各有关部门、直属机构，中央军委科学技术委员会，各有关单位：</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国家重点实验室是国家组织开展基础研究和应用基础研究、聚集和培养优秀科技人才、开展高水平学术交流、具备先进科研装备的重要科技创新基地，是国家创新体系的重要组成部分。经过</span><span style="font-family:宋体">30多年的建设发展，已成为孕育重大原始创新、推动学科发展和解决国家战略重大科学技术问题的重要力量。但与全面加强基础科学研究建设世界科技强国的要求相比，还存在重大原创性成果缺乏、世界一流领军科学家不足、管理体制机制亟待深化等问题。为进一步加强国家重点实验室建设发展，依据《关于深化中央财政科技计划（专项、基金等）管理改革的方案》（国发〔2014〕64号）、《国务院关于全面加强基础科学研究的若干意见》（国发〔2018〕4号）和《国家科技创新基地优化整合方案》（国科发基〔2017〕250号），现提出以下意见。</span></span></p><p style="line-height:29px"><span style=";font-family:黑体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十九大精神，以习近平新时代中国特色社会主义思想为指导，以加快建设创新型国家为目标，面向世界科技前沿、面向国家重大需求、面向国民经济主战场，加强顶层设计和系统布局，加大建设力度和体制机制创新，强化基础研究和应用基础研究，凝聚和培养一流优秀人才，引领未来科学技术发展方向，产出重大原创成果，大幅提升国家重点实验室的原始创新能力、国际学术影响力、学科发展带动力、国家需求和社会发展支撑力，打造国家重点实验室</span><span style="font-family:宋体">“升级版”，保持国家重点实验室的创新性、先进性和引领性，构筑国际竞争新优势，促进基础研究与应用研究融通发展，为建设世界科技强国提供有力支撑。</span></span></p><p style="line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——坚持系统布局。按照建设高水平科学与工程研究类国家科技创新基地的要求，加强顶层设计，构建国家重点实验室发展体系，明确各类国家重点实验室功能定位、目标任务。</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——坚持能力提升。加强创新能力建设，注重原始创新，聚集领军人才，增强国家重点实验室持续创新活力，促进重大原创成果产出，提升国际影响力。</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——坚持开放合作。深化“开放、流动、联合、竞争”机制建设，强化开放合作，加强协同创新，推动军民融合，激发创新活力，提升服务能力。</span></span></p><p style="line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——坚持科学管理。加强制度建设，强化分类管理，完善评估机制。加强统筹协调，发挥部门地方作用。建立多元投入机制，强化财政稳定支持。</span></span></p><p style="line-',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('43','国务院办公厅关于推动国防科技工业 军民融合深度发展的意见','产业','其他','全国（000000 QG）','国办发〔2017〕91号','国务院令（行政法规）','国务院办公厅','2017-11-23','2022-06-21','2017-11-23',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国防科技工业是军民融合发展的重点领域，是实施军民融合发展战略的重要组成部分，对提升中国特色先进国防科技工业水平、支撑国防军队建设、推动科学技术进步、服务经济社会发展具有重要意义。当前和今后一个时期是军民融合发展的战略机遇期，也是军民融合由初步融合向深度融合过渡、进而实现跨越发展的关键期，国防科技工业领域军民融合潜力巨大。为推动国防科技工业军民融合深度发展，经国务院同意，现提出以下意见：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻落实党的十九大精神，坚持以习近平新时代中国特色社会主义思想为指导，认真落实党中央、国务院决策部署，统筹推进</span><span style="font-family:宋体">“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立和贯彻落实新发展理念，以军民融合发展战略为引领，突出问题导向，聚焦重点领域，完善政策法规，落实改革举措，推进军民结合、寓军于民的武器装备科研生产体系建设，实现军民资源互通共享和相互支撑、有效转化，推动国防科技工业军民融合深度发展，建设中国特色先进国防科技工业体系。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="text-indent:32px;text-align:justify;text-justify:distribute-all-lines;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——国家主导，市场运作。在中央统一领导下，加强国防科技工业军民融合政策引导、制度创新，健全完善政策，打破行业壁垒，推动军民资源互通共享。充分发挥市场在资源配置中的作用，激发各类市场主体活力，推动公平竞争，实现优胜劣汰，促进技术进步和产业发展，加快形成全要素、多领域、高效益的军</span></span></p><p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">民融合深度发展格局。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——问题导向，务求实效。针对制约国防科技工业军民融合深度发展的障碍，围绕“军转民”、“民参军”、军民两用技术产业化、军民资源互通共享等重点领域，突出解决深层次和重点、难点问题，向更广范围、更高层次、更深程度推动军民融合发展。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——协同推进，成熟先行。充分发挥有关部门和地方政府作用，调动军工集团公司、军队科研单位和中科院、高等学校以及包括民营企业在内的其他民口单位等多方面积极性，形成各方密切合作、协同推进的强大合力。注重政策统筹协调，有序推进，成熟一项、落实一项。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、进一步扩大军工开放</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）推动军品科研生产能力结构调整。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">打破军工和民口界限，不分所有制性质，制定军品科研生产能力结构调整方案，对全社会军品科研生产能力进行分类管理，形成小核心、大协作、专业化、开放型武器装备科研生产体系。核心能力由国家主导；重要能力发挥国家主导和市场机制作用，促进竞争，择优扶强；一般能力完全放开，充分竞争。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（四）扩大军工单位外部协作。</span></span><s',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('44','国务院办公厅关于深化产教融合的若干意见','产业','其他','全国（000000 QG）','国办发〔2017〕95号','国务院令（行政法规）','国务院办公厅','2017-12-05','2022-06-21','2017-12-05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">进入新世纪以来，我国教育事业蓬勃发展，为社会主义现代化建设培养输送了大批高素质人才，为加快发展壮大现代产业体系作出了重大贡献。但同时，受体制机制等多种因素影响，人才培养供给侧和产业需求侧在结构、质量、水平上还不能完全适应，</span><span style="font-family:宋体">“两张皮”问题仍然存在。深化产教融合，促进教育链、人才链与产业链、创新链有机衔接，是当前推进人力资源供给侧结构性改革的迫切要求，对新形势下全面提高教育质量、扩大就业创业、推进经济转型升级、培育经济发展新动能具有重要意义。为贯彻落实党的十九大精神，深化产教融合，全面提升人力资源质量，经国务院同意，现提出以下意见。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十九大精神，坚持以习近平新时代中国特色社会主义思想为指导，紧紧围绕统筹推进</span><span style="font-family:宋体">“五位一体”总体布局和协调推进“四个全面”战略布局，坚持以人民为中心，坚持新发展理念，认真落实党中央、国务院关于教育综合改革的决策部署，深化职业教育、高等教育等改革，发挥企业重要主体作用，促进人才培养供给侧和产业需求侧结构要素全方位融合，培养大批高素质创新人才和技术技能人才，为加快建设实体经济、科技创新、现代金融、人力资源协同发展的产业体系，增强产业核心竞争力，汇聚发展新动能提供有力支撑。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）原则和目标。</span></span></p><p style="text-indent:32px;text-align:justify;text-justify:distribute-all-lines;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">统筹协调，共同推进。将产教融合作为促进经济社会协调发展的重要举措，融入经济转型升级各环节，贯穿人才开发全过程，形成政府企业学校行业社会协</span></span></p><p style=";line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">同推进的工作格局。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">服务需求，优化结构。面向产业和区域发展需求，完善教育资源布局，加快人才培养结构调整，创新教育组织形态，促进教育和产业联动发展。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;letter-spacing:0;font-size:16px"><span style="font-family:宋体">校企协同，合作育人。充分调动企业参与产教融合的积极性和主动性，强化政策引导，鼓励先行先试，促进供需对接和流程再造，构建校企合作长效机制。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">深化产教融合的主要目标是，逐步提高行业企业参与办学程度，健全多元化办学体制，全面推行校企协同育人，用</span><span style="font-family:宋体">10年左右时间，教育和产业统筹融合、良性互动的发展格局总体形成，需求导向的人才培养模式健全完善，人才教育供给与产业需求重大结构性矛盾基本解决，职业教育、高等教育对经济发展和产业升级的贡献显著增强。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、构建教育和产业统筹融合发展格局</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）同步规划产教融合与经济社会发展。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">制定实施经济社会发展规划',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('46','国务院办公厅关于支持国家级新区 深化改革创新加快推动高质量发展的指导意见','创新载体','其他','全国（000000 QG）','国办发〔2019〕58号','国务院令（行政法规）','国务院办公厅','2019-12-31','2022-06-21','2019-12-31',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国家级新区（以下简称新区）是承担国家重大发展和改革开放战略任务的综合功能平台。自上世纪</span><span style="font-family:宋体">90年代以来，新区建设发展取得了显著成效，但也不同程度地面临规划建设不够集约节约、主导产业优势不够突出、管理体制机制不够健全、改革创新和全方位开放不够深化等问题。为促进新区加大创新创业力度，加强改革系统集成，扩大高水平开放，打造实体经济发展高地，引领高质量发展，经国务院同意，现提出以下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会精神，坚持稳中求进工作总基调，坚持新发展理念，坚持以供给侧结构性改革为主线，突出高起点规划、高标准建设、高水平开放、高质量发展，用改革的办法和市场化、法治化的手段，大力培育新动能、激发新活力、塑造新优势，努力成为高质量发展引领区、改革开放新高地、城市建设新标杆。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——实体为本，持续增强竞争优势。把推动制造业高质量发展放在突出位置，深化供给侧结构性改革，对接国际标准，适应发展趋势，遵循市场化原则，科学培育并紧紧围绕主导产业，突破一批关键核心技术，培育新业态新模式，促进新旧动能顺畅转换，做实做强做优实体经济。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——刀刃向内，加快完善体制机制。坚持向改革创新要动力，赋予新区更大改革自主权，发挥综合功能平台优势，加强改革系统集成探索，巩固在解决体制性障碍、机制性梗阻和强化政策性创新等方面取得的改革成果，注重各项改革协调推进、相得益彰，推动制度优势转化为治理效能。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——主动对标，全面提升开放水平。支持新区率先复制自贸试验区改革开放经验，对接国际先进规则，深度参与全球产业分工，在更深层次、更宽领域，以更大力度推进全方位高水平开放，不断提升国际市场影响力和竞争力。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——尊重规律，合理把握开发节奏。保持历史耐心和战略定力，高质量高标准推动新区规划建设。准确定位、突出优势和特色，处理好有所为与有所不为、先为与后为、快为与慢为的关系，尊重城市发展规律，合理把握开发节奏，促进绿色低碳发展，坚决防止盲目建设和无序扩张。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、着力提升关键领域科技创新能力</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）打造若干竞争力强的创新平台。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('47','科技部办公厅关于加快推动国家科技成果转移转化示范区 建设发展的通知','创新载体','其他','全国（000000 QG）','国科办区〔2020〕50号','国务院令（行政法规）','科技部办公厅','2020-06-04','2022-06-21','2020-06-04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局），新疆生产建设兵团科技局，各相关管理单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国家科技成果转移转化示范区（以下简称</span><span style="font-family:宋体">“示范区”）是实施创新驱动发展战略的重要载体，是创新科技成果转移转化机制的试验田，是促进科技与经济社会融合发展的先行区。按照国家技术转移体系建设的任务要求，科技部已批复建设江苏苏南、四川成德绵等9家示范区，为探索科技成果转化机制和推进全面创新发展提供了经验和示范。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深入贯彻党中央、国务院关于创新促进科技成果转化机制的部署要求，积极开展科技成果转化先行先试，优化创新创业生态，打通产学研相结合的创新链、产业链和价值链，充分发挥示范区示范带动作用，统筹推进科技支撑</span><span style="font-family:宋体">“六稳”工作和“六保”任务，以科技成果转化引领示范区高质量发展，现就有关事项通知如下。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、以服务科技型企业为重点，发挥支撑复工复产示范带动作用。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">示范区要全面落实科技支撑复工复产和经济平稳运行的若干措施。以实施</span><span style="font-family:宋体">“百城百园”行动为抓手，加快项目建设，扶持科技型企业发展，以创新创业带动就业。加强协调组织，通过成果转化助力示范区成为新基建、新技术、新材料、新装备、新产品、新业态的主阵地，培育一批科技成果转化示范企业。实施科技人员服务企业专项行动，推动科技特派员、科技专家服务团等参与企业科技成果转化，积极开展技术转让、技术许可、技术开发、技术咨询和技术服务等活动。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、以创新促进科技成果转化机制模式为重点，进一步加大先行先试力度。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">示范区要坚持以供给侧结构性改革为主线，发挥企业主体和政府统筹作用，进一步创新科技成果转化机制，促进技术、资金、应用、市场等对接，着力推进以需求为导向的市场化科技成果转化机制先行先试。鼓励有条件的示范区开展赋予科研人员职务科技成果所有权或长期使用权试点。健全以转化应用为导向的科技成果评价机制。规范简化科技成果转化审批程序，完善科技成果转化容错纠错机制，实行审慎包容监管。探索知识产权证券化，有序建设知识产权和科技成果产权交易中心，完善科技成果转化公开交易与监管机制。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">三、以强化科技成果转化全链条服务为重点，提高成果转化专业化服务能力。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">示范区要加强综合性科技创新公共服务平台建设，着力提升科技成果、产业服务、科技金融、市场应用等公共科技服务能力。建立绩效奖励机制，支持各类技术转移机构发展。在高等学校中开展国家技术转移中心建设试点，培育和发展一批特色明显、服务能力突出的专业化技术转移机构，支持社会化技术转移机构为高等学校、科研院所和科技企业提供服务。建设职业化技术转移人才培养基地，将技术转移人才纳入相关人才计划，推动建立技术转移职业技能等级制度。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">四、以示范区主导产业为重点，加快推进重大科技成果转化应用。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">示范区要聚焦高新区、农高区等科技园区主导产业，加快培育新兴产业和创新型产业集群，定期发布技术需求清单和新技术应用场景清单，建立以企业为主体的科技成果转化中试熟化基地，加强产学研协同技术攻关与成果转化应用。支持承担国家科技计划项目的企业，在示范区开展成果落地转化。依托先进技术成果信息共享服务平台，委托第三方建立示范区</span><span style="font-family:宋体">“定制化”技术成果供给清单。针对医疗卫生、生态环保、公共安全、乡村振兴等重大民生需求，示范区积极组织开展形式多样的科技成果进基层、进园区、进乡村等活动，推动科技成',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('55','科技部印发《关于新时期支持科技型中小企业加快创新发展的若干政策措施》的通知','企业','其他','全国（000000 QG）','国科发区〔2019〕268号','国务院令（行政法规）','科 技 部','2019-08-05','2022-06-21','2019-08-05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局），新疆生产建设兵团科技局：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深入贯彻落实党中央、国务院支持民营企业发展的重大决策部署，加快推动民营企业特别是各类中小企业走创新驱动发展道路，强化对科技型中小企业的政策引导与精准支持，科技部制订了《关于新时期支持科技型中小企业加快创新发展的若干政策措施》。现印发给你们，请结合实际，认真贯彻执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科</span> <span style="font-family:宋体">技</span> <span style="font-family:宋体">部</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2019年8月5日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件主动公开）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">关于新时期支持科技型中小企业加快创新发展的若干政策措施</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科技型中小企业是培育发展新动能、推动高质量发展的重要力量，科技创新能力是企业打不垮的竞争力。为深入贯彻习近平总书记在民营企业座谈会上的重要讲话精神，切实落实中央办公厅、国务院办公厅《关于促进中小企业健康发展的指导意见》，加快推动民营企业特别是各类中小企业走创新驱动发展道路，增强技术创新能力与核心竞争力，现就支持科技型中小企业创新发展提出以下政策措施。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体思路</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，以培育壮大科技型中小企业主体规模、提升科技型中小企业创新能力为主要着力点，完善科技创新政策，加强创新服务供给，激发创新创业活力，引导科技型中小企业加大研发投入，完善技术创新体系，增强以科技创新为核心的企业竞争力，为推动高质量发展、支撑现代化经济体系建设发挥更加重要的作用。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、主要措施</span></span></p><p style="text-indent:32px;t',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('56','科技部办公厅关于营造更好环境支持 科技型中小企业研发的通知','企业','其他','全国（000000 QG）','国科办区〔2022〕2号','国务院令（行政法规）','科技部办公厅','2022-01-11','2022-06-21','2022-01-11',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局），新疆生产建设兵团科技局：</span></span></p><p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">科技型中小企业技术含量高、创新能力强，是极具活力和潜力的创新主体，是强化企业创新主体地位的重要力量。为贯彻落实党的十九大和十九届历次全会精神，以及中央经济工作会议精神，营造更好环境支持科技型中小企业研发，促进科技型中小企业成长为创新重要发源地。现将有关事项通知如下。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，坚决贯彻落实党中央、国务院决策部署，立足新发展阶段、贯彻新发展理念、构建新发展格局，以支持科技型中小企业研发为主线，推动科技、金融、财税等政策加大落实力度，从优化资助模式、完善政策措施、集聚高端人才、创造应用场景、夯实创新创业基础条件等方面，形成支持科技型中小企业研发的制度安排，支持科技型中小企业开展关键核心技术攻关，大幅提升中小企业研发能力，推动高水平科技自立自强。</span></span></p><p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）主要目标。</span></span><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">到</span><span style="font-family:宋体">“十四五”末，形成支持科技型中小企业研发的制度体系，营造全社会支持中小企业研发的环境氛围，科技型中小企业数量新增20万家。增强科技型中小企业研发能力，实现“四科”标准科技型中小企业新增5万家（即每个科技企业要拥有关键核心技术的科技产品、科技人员占比大于60%、以高价值知识产权为代表的科技成果超过5项、研发投入强度高于6%）。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、优化支持科技型中小企业研发的资助模式</span></span></p><p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）优化科技计划支持研发的机制。</span></span><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">在国家重点研发计划重点专项中，单列一定预算资助科技型中小企业研发活动，精准支持具备条件的科技型中小企业承担国家科技任务，开展关键核心技术攻关，引导创新要素向企业聚集，加快培养一批研发能力强、技术水平高、科技人才密集、能够形成核心技术产品等</span><span style="font-family:宋体">“四科”特征明显的科技型中小企业。</span></span></p><p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（四）优化政府引导基金支持研发的机制。</span></span><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">优化国家科技成果转化引导基金绩效评价制度，将支持科技型中小企业突破关键核心技术作为重要绩效考核指标。支持国家、地方及行业各类科技成果转化引导基金设立科技型中小企业子基金，鼓励有',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('62','中共科学技术部党组关于创新驱动乡村振兴发展的意见','农村科技与社会发展','其他','全国（000000 QG）','国科党组发〔2018〕36号','国务院令（行政法规）',' 中共科学技术部党组 ','2018-08-07','2022-06-21','2018-08-07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">实施乡村振兴战略，是党的十九大作出的重大决策部署，是决胜全面建成小康社会、全面建设社会主义现代化国家的重大历史任务，是新时代</span><span style="font-family:宋体">“三农”工作的总抓手。实施乡村振兴战略的本质是推进农业农村现代化，农业农村现代化的关键在科技进步，创新是实现乡村振兴的战略支撑。为深入贯彻落实创新驱动发展战略和乡村振兴战略，现就创新驱动乡村振兴发展提出以下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、重大意义</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">党的十八大以来，以习近平同志为核心的党中央坚持把解决好</span><span style="font-family:宋体">“三农”问题作为全党工作重中之重，高度重视农业农村科技创新工作，我国科技支撑农业农村发展取得历史性成就。农业农村科技水平大幅提高，农业科技进步贡献率由2012年的53.5%提高到2017年的57.5%。粮食安全的科技支撑进一步增强，主要农作物良种实现全覆盖。农业劳动生产率显著提高，主要农作物耕种收综合机械化水平超过66%。农业高新技术产业不断壮大，农村新产业新业态蓬勃发展。农业农村科技发展取得的重大成就和积累的丰富经验，为创新驱动乡村振兴发展奠定了良好基础和有利条件。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">农业农村农民问题是关系国计民生的根本性问题。没有农业农村的现代化，就没有国家的现代化。当前，农业是现代化建设的短腿，农村是全面建成小康社会的短板，我国发展不平衡不充分问题在农业农村领域尤为突出。农业农村科技创新仍然存在诸多问题，主要表现在：农业农村科技创新体系不健全，创新主体不强；农业农村科技投入不足，科技供给水平不高；土地产出率、劳动生产率不高，产业竞争力不强；绿色发展水平低，农业农村环境亟待改善；农业农村各类资源要素难以集聚，资金、人才流失严重。创新驱动乡村振兴发展，是加快农业农村现代化的必然要求。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">在中国特色社会主义新时代，以科技创新为核心的全面创新已经成为推动我国经济社会发展的强大动力，我们完全有信心有能力依靠创新驱动乡村振兴发展。科技战线必须立足世情国情科情农情，切实增强责任感使命感紧迫感，必须强化创新驱动能力，加快农业科技进步，为乡村振兴插上科技的翅膀，为保障国家粮食安全、食品安全和生态安全，推进农业全面升级、农村全面进步、农民全面发展提供战略支撑。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">二、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十九大和十九届二中、三中全会精神，以习近平新时代中国特色社会主义思想为指导，加强党对</span><span style="font-family:宋体">“三农”工作的领导，坚持稳中求进工作总基调，牢固树立新发展理念，落实高质量发展要求，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求，以创新驱动乡村振兴发展，统筹部署农业农村领域基础研究、应用基础研究和技术创新工程，推动科学研究、基地建设、人才队伍一体化发展，打造农业农村战略科技力量，提高农业创新力、竞争力和全要素生产率，为加快推进农业农村现代化提供科技支撑，走中国特色社会主义乡村振兴道路，让农业成为有奔头的产业，让农民成为有吸引力的职业，让农村成为安居乐业的美丽家园。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-si',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('63','科技部 中国农业银行 印发《关于加强现代农业科技金融服务创新支撑乡村振兴 战略实施的意见》的通知','农村科技与社会发展','其他','全国（000000 QG）','国科发农技〔2021〕95号','国务院令（行政法规）','科 技 部 中国农业银行','2021-04-20','2022-06-21','2021-04-20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局），新疆生产建设兵团科技局，中国农业银行各省、自治区、直辖市分行，新疆兵团分行，各直属分行：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">为进一步加强现代农业科技金融服务，科技部、中国农业银行联合制定了《关于加强现代农业科技金融服务</span> <span style="font-family:宋体">创新支撑乡村振兴战略实施的意见》，现印发给你们，请结合本地实际认真贯彻执行。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">科</span> <span style="font-family:宋体">技</span> <span style="font-family:宋体">部</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">中国农业银行</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">2021年4月20日</span></span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">关于加强现代农业科技金融服务创新支撑乡村振兴战略实施的意见</span></span></strong></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ide',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('65','中共中央印发《关于深化人才发展体制机制改革的意见》','科技人才','其他','全国（000000 QG）','中发〔2016〕9号','国务院令（行政法规）','中共中央','2016-03-21','2022-06-21','2016-03-21',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">人才是经济社会发展的第一资源。人才发展体制机制改革是全面深化改革的重要组成部分，是党的建设制度改革的重要内容。协调推进</span><span style="font-family:宋体">“四个全面”战略布局，贯彻落实创新、协调、绿色、开放、共享的发展理念，实现“两个一百年”奋斗目标，必须深化人才发展体制机制改革，加快建设人才强国，最大限度激发人才创新创造创业活力，把各方面优秀人才集聚到党和国家事业中来。现就深化人才发展体制机制改革提出如下意见。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、指导思想、基本原则和主要目标</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">高举中国特色社会主义伟大旗帜，全面贯彻党的十八大和十八届三中、四中、五中全会精神，以邓小平理论、</span><span style="font-family:宋体">“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，坚持聚天下英才而用之，牢固树立科学人才观，深入实施人才优先发展战略，遵循社会主义市场经济规律和人才成长规律，破除束缚人才发展的思想观念和体制机制障碍，解放和增强人才活力，构建科学规范、开放包容、运行高效的人才发展治理体系，形成具有国际竞争力的人才制度优势。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——坚持党管人才。充分发挥党的思想政治优势、组织优势和密切联系群众优势，进一步加强和改进党对人才工作的领导，健全党管人才领导体制和工作格局，创新党管人才方式方法，为深化人才发展体制机制改革提供坚强的政治和组织保证。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——服务发展大局。围绕经济社会发展需求，聚焦国家重大战略，科学谋划改革思路和政策措施，促进人才规模、质量和结构与经济社会发展相适应、相协调，实现人才发展与经济建设、政治建设、文化建设、社会建设、生态文明建设深度融合。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——突出市场导向。充分发挥市场在人才资源配置中的决定性作用和更好发挥政府作用，加快转变政府人才管理职能，保障和落实用人主体自主权，提高人才横向和纵向流动性，健全人才评价、流动、激励机制，最大限度激发和释放人才创新创造创业活力，使人才各尽其能、各展其长、各得其所，让人才价值得到充分尊重和实现。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——体现分类施策。根据不同领域、行业特点，坚持从实际出发，具体问题具体分析，增强改革针对性、精准性。纠正人才管理中存在的行政化、“官本位”倾向，防止简单套用党政领导干部管理办法管理科研教学机构学术领导人员和专业人才。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——扩大人才开放。树立全球视野和战略眼光，充分开发利用国内国际人才资源，主动参与国际人才竞争，完善更加开放、更加灵活的人才培养、吸引和使用机制，不唯地域引进人才，不求所有开发人才，不拘一格用好人才，确保人才引得进、留得住、流得动、用得好。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）主要目标</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">通过深化改革，到</span><span style="font-family:宋体">2020年，在人才发展体制机制的重要领域和关键环节上取得突破性进展，人才管理体制更加科学高效，人才评价、流动、激励机制更加完善，全社会识才爱才敬才用才氛围更加浓厚，形成与社会主义市场经济体制相适应、人人皆可成才、人人尽展其才的政策法律体系和社会环境。</span></span></p><p style="text-indent:32px;line-height:29px"',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('66','国务院关于激发重点群体活力带动城乡居民增收的实施意见','科技人才','其他','全国（000000 QG）','国发〔2016〕56号','国务院令（行政法规）',' 国务院','2016-10-10','2022-06-21','2016-10-10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">提高城乡居民收入是全面建成小康社会的重要内容，体现社会主义本质的必然要求。党的十八大提出，要千方百计增加居民收入。党的十八届三中全会提出，要形成合理有序的收入分配格局。党的十八届五中全会提出，在提高发展平衡性、包容性、可持续性的基础上，到</span><span style="font-family:宋体">2020年国内生产总值和城乡居民人均收入比2010年翻一番。按照党中央、国务院决策部署，为营造激励奋发向上的公平环境，拓宽就业渠道，促进各类社会群体依靠自身努力和智慧，创造社会财富，共享发展红利，现提出以下实施意见。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）基本形势。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">改革开放以来，我国城乡居民收入保持持续较快增长，收入分配结构呈现向好趋势。从放权让利到允许一部分人、一部分地区先富起来，到要素参与分配，适应我国国情的分配制度基本确立，收入分配政策推动了经济社会发展，促进了各类社会群体依靠自身努力和智慧，创造社会财富，共享发展红利，为深化改革开放注入了动力和活力。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">当前，经济运行的新常态特征更加明显，新技术、新产业、新业态加速成长，培育壮大新动能，改造提升传统动能，正在不断创造出新的就业岗位，为促进城乡居民收入稳定增长提供了有力支撑。但受国内外多重因素影响，经济下行压力也正在向收入分配领域传导。既要降低经济运行成本、保持经济中高速增长，又要提高居民收入、不断增进人民福祉，实现居民收入增长和经济增长同步、劳动报酬提高和劳动生产率提高同步任重而道远。同时，部分劳动者人力资本积累不足、增收困难，部分市场主体等待观望，部分地区行业收入增长潜在动能不强，部分收入分配政策指向宽泛、聚焦不够。为推动解决相关问题，必须进一步深化收入分配制度改革，调整优化收入分配政策，拓宽就业创业渠道，努力营造激励奋发向上的公平环境。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）指导思想。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">全面贯彻落实党的十八大和十八届三中、四中、五中全会精神，深入贯彻习近平总书记系列重要讲话精神，统筹推进</span><span style="font-family:宋体">“五位一体”总体布局，协调推进“四个全面”战略布局，牢固树立和贯彻落实创新、协调、绿色、开放、共享的发展理念，按照党中央、国务院决策部署，坚持以人民为中心的发展思想，做到发展为了人民、发展依靠人民、发展成果由人民共享。围绕加快实施创新驱动发展战略、推动大众创业万众创新、培育发展新动能、改造提升传统动能，着力推进供给侧结构性改革，不断深化简政放权、放管结合、优化服务改革，进一步深化收入分配制度改革，强化收入分配政策激励导向，分群体施策，不断激发全体劳动者的积极性、主动性、创造性，实现经济增长与居民增收互促共进，使全体人民在共建共享发展中有更多获得感，朝着共同富裕方向稳步前进。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）基本原则。</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">坚持多种激励方式相结合。物质激励和精神激励并用，综合运用增加薪资报酬、强化权利保护、优化评优奖励、提升职业技能、增进社会认同等多种激励手段，调动不同群体的积极性、主动性和创造性。完善绩效考核制度，将激励与考核挂钩。</span></span></p><p style="text-indent:32px;line-height:29px;bac',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('74','科技部 教育部印发《关于进一步推进高等学校专业化技术转移机构建设发展的实施意见》的通知','科技中介服务','其他','全国（000000 QG）','国科发区〔2020〕133号','国务院令（行政法规）','科技部 教育部','2020-05-13','2022-06-21','2020-05-13',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市及计划单列市科技厅（委、局）、教育厅（教委），新疆生产建设兵团科技局、教育局，国务院各有关部门科技主管司局，部属各高等学校、部省合建各高等学校，各有关单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为贯彻落实《中共中央</span> <span style="font-family:宋体">国务院关于构建更加完善的要素市场化配置体制机制的意见》和《国家技术转移体系建设方案》（国发〔</span><span style="font-family:宋体">2017〕44号）要求，创新促进科技成果转化机制，进一步提升高校科技成果转移转化能力，科技部、教育部研究制定了《关于进一步推进高等学校专业化技术转移机构建设发展的实施意见》，现印发给你们，请结合实际，加快推进落实。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科技部</span> <span style="font-family:宋体">教育部</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2020年5月13日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件主动公开）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">关于进一步推进高等学校专业化技术转移机构建设发展的实施意见</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">高校技术转移机构建设是国家技术转移体系的重要组成部分。为贯彻落实《中共中央</span> <span style="font-family:宋体">国务院关于构建更加完善的要素市场化配置体制机制的意见》和《国家技术转移体系建设方案》（国发〔</span><span style="font-family:宋体">2017〕44号），进一步提升高校科技成果转移转化能力，现就推进高校技术转移机构高质量建设和专业化发展，提出以下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的十九大和十九届二中、三中、四中全会精神，坚',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('75','国务院关于推动创新创业高质量发展打造 “双创”升级版的意见','科技中介服务','其他','全国（000000 QG）','国发〔2018〕32号','国务院令（行政法规）','国务院','2018-09-18','2022-06-21','2018-09-18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新是引领发展的第一动力，是建设现代化经济体系的战略支撑。近年来，大众创业万众创新持续向更大范围、更高层次和更深程度推进，创新创业与经济社会发展深度融合，对推动新旧动能转换和经济结构升级、扩大就业和改善民生、实现机会公平和社会纵向流动发挥了重要作用，为促进经济增长提供了有力支撑。当前，我国经济已由高速增长阶段转向高质量发展阶段，对推动大众创业万众创新提出了新的更高要求。为深入实施创新驱动发展战略，进一步激发市场活力和社会创造力，现就推动创新创业高质量发展、打造</span><span style="font-family:宋体">“双创”升级版提出以下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">推进大众创业万众创新是深入实施创新驱动发展战略的重要支撑、深入推进供给侧结构性改革的重要途径。随着大众创业万众创新蓬勃发展，创新创业环境持续改善，创新创业主体日益多元，各类支撑平台不断丰富，创新创业社会氛围更加浓厚，创新创业理念日益深入人心，取得显著成效。但同时，还存在创新创业生态不够完善、科技成果转化机制尚不健全、大中小企业融通发展还不充分、创新创业国际合作不够深入以及部分政策落实不到位等问题。打造</span><span style="font-family:宋体">“双创”升级版，推动创新创业高质量发展，有利于进一步增强创业带动就业能力，有利于提升科技创新和产业发展活力，有利于创造优质供给和扩大有效需求，对增强经济发展内生动力具有重要意义。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，坚持新发展理念，坚持以供给侧结构性改革为主线，按照高质量发展要求，深入实施创新驱动发展战略，通过打造</span><span style="font-family:宋体">“双创”升级版，进一步优化创新创业环境，大幅降低创新创业成本，提升创业带动就业能力，增强科技创新引领作用，提升支撑平台服务能力，推动形成线上线下结合、产学研用协同、大中小企业融合的创新创业格局，为加快培育发展新动能、实现更充分就业和经济高质量发展提供坚实保障。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）主要目标。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——创新创业服务全面升级。创新创业资源共享平台更加完善，市场化、专业化众创空间功能不断拓展，创新创业服务平台能力显著提升，创业投资持续增长并更加关注早中期科技型企业，新兴创新创业服务业态日趋成熟。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——创业带动就业能力明显提升。培育更多充满活力、持续稳定经营的市场主体，直接创造更多就业岗位，带动关联产业就业岗位增加，促进就业机会公平和社会纵向流动，实现创新、创业、就业的良性循环。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">——科技成果转化应用能力显著增强。科技型创业加快发展，产学研用更加协同，科技创新与传统产业转型升级结合更加紧密，形成多层次科技创新和产业发展主体，支撑战略性新兴产业加快发展。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('83','财政部 海关总署 税务总局 关于“十四五”期间支持科普事业发展进口税收政策的通知','科技金融与税收','其他','全国（000000 QG）','财关税[2021]26号','国务院令（行政法规）','财政部  海关总署  税务总局','2021-04-09','2022-06-21','2021-04-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市、计划单列市财政厅</span><span style="font-family:宋体">(局)、新疆生产建设兵团财政局，海关总署广东分署、各直属海关，国家税务总局各省、自治区、直辖市、计划单列市税务局，财政部各地监管局，国家税务总局驻各地特派员办事处：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">为支持科普事业发展，现将有关进口税收政策通知如下：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">一、自</span><span style="font-family:宋体">2021年1月1日至2025年12月31日，对公众开放的科技馆、自然博物馆、天文馆(站、台)、气象台(站)、地震台(站)，以及高校和科研机构所属对外开放的科普基地，进口以下商品免征进口关税和进口环节增值税：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">(一)为从境外购买自用科普影视作品播映权而进口的拷贝、工作带、硬盘，以及以其他形式进口自用的承载科普影视作品的拷贝、工作带、硬盘。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">(二)国内不能生产或性能不能满足需求的自用科普仪器设备、科普展品、科普专用软件等科普用品。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">二、第一条中的科普影视作品、科普用品是指符合科学技术普及法规定，以普及科学知识、倡导科学方法、传播科学思想、弘扬科学精神为宗旨的影视作品、科普仪器设备、科普展品、科普专用软件等用品。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">三、第一条第一项中的科普影视作品相关免税进口商品清单见附件。第一条第二项中的科普用品由科技部会同有关部门核定。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">四、</span><span style="font-family:宋体">“十四五”期间支持科普事业发展进口税收政策管理办法由财政部、海关总署、税务总局会同有关部门另行制定印发。</span></span></p><p style="margin-top:0;margin-right:0;margin-b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('84','关于进一步提高科技型中小企业研发费用税前 加计扣除比例的公告','科技金融与税收','其他','全国（000000 QG）','财政部 税务总局 科技部公告2022年第16号','国务院令（行政法规）','财政部  税务总局  科技部','2022-03-23','2022-06-21','2022-03-23',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-right: 0;margin-left: 0;text-indent: 0;padding: 0;line-height:29px;background: rgb(255, 255, 255)"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px"><span style="font-family:宋体">为进一步支持科技创新，鼓励科技型中小企业加大研发投入，现就提高科技型中小企业研究开发费用（以下简称研发费用）税前加计扣除比例有关问题公告如下：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">一、科技型中小企业开展研发活动中实际发生的研发费用，未形成无形资产计入当期损益的，在按规定据实扣除的基础上，自</span><span style="font-family:宋体">2022年1月1日起，再按照实际发生额的100%在税前加计扣除；形成无形资产的，自2022年1月1日起，按照无形资产成本的200%在税前摊销。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">二、科技型中小企业条件和管理办法按照《科技部</span><span style="font-family:宋体">&nbsp;财政部&nbsp;国家税务总局关于印发&lt;科技型中小企业评价办法&gt;的通知》（国科发政〔2017〕115号）执行。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">三、科技型中小企业享受研发费用税前加计扣除政策的其他政策口径和管理要求，按照《财政部</span><span style="font-family:宋体">&nbsp;国家税务总局&nbsp;科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）、《财政部&nbsp;税务总局&nbsp;科技部关于企业委托境外研究开发费用税前加计扣除有关政策问题的通知》（财税〔2018〕64号）等文件相关规定执行。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">四、本公告自</span><span style="font-family:宋体">2022年1月1日起执行。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">财政部</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('91','国务院办公厅关于完善科技成果评价机制的指导意见','科技成果与知识产权','其他','全国（000000 QG）','国办发〔2021〕26号','国务院令（行政法规）','国务院办公厅','2021-07-16','2022-06-21','2021-07-16',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">为健全完善科技成果评价体系，更好发挥科技成果评价作用，促进科技与经济社会发展更加紧密结合，加快推动科技成果转化为现实生产力，经国务院同意，现提出如下意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）指导思想。</span></span><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，深入贯彻党的十九大和十九届二中、三中、四中、五中全会精神，深入实施创新驱动发展战略，深化科技体制改革，坚持正确的科技成果评价导向，创新科技成果评价方式，通过评价激发科技人员积极性，推动产出高质量成果、营造良好创新生态，促进创新链、产业链、价值链深度融合，为构建新发展格局和实现高质量发展提供有力支撑。</span></span></p><p style=";padding: 0;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）基本原则。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">坚持科技创新质量、绩效、贡献为核心的评价导向。充分发挥科技成果评价的</span><span style="font-family:宋体">“指挥棒”作用，全面准确反映成果创新水平、转化应用绩效和对经济社会发展的实际贡献，着力强化成果高质量供给与转化应用。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">坚持科学分类、多维度评价。针对科技成果具有多元价值的特点，科学确定评价标准，开展多层次差别化评价，提高成果评价的标准化、规范化水平，解决分类评价体系不健全以及评价指标单一化、标准定量化、结果功利化的问题。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">坚持正确处理政府和市场关系。充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，引入第三方评价，加快技术市场建设，加快构建政府、社会组织、企业、投融资机构等共同参与的多元评价体系，充分调动各类评价主体的积极性，营造成果评价的良好创新生态。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体"',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('92','国务院办公厅关于印发 《知识产权对外转让有关工作办法（试行）》的通知','科技成果与知识产权','其他','全国（000000 QG）','国办发〔2018〕19号','国务院令（行政法规）',' 国务院办公厅','2018-03-18','2022-06-21','2018-03-18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院各部委、各直属机构：</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">《知识产权对外转让有关工作办法（试行）》已经国务院同意，现印发给你们，请认真贯彻执行。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family:宋体">国务院办公厅</span> </span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family:宋体">2018年3月18日 </span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件公开发布）</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><br/></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">知识产权对外转让有关工作办法（试行）</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为贯彻落实总体国家安全观，完善国家安全制度体系，维护国家安全和重大公共利益，规范知识产权对外转让秩序，依据国家安全、对外贸易、知识产权等相关法律法规，制定本办法。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、审查范围</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（一）技术出口、外国投资者并购境内企业等活动中涉及本办法规定的专利权、集成电路布图设计专有权、计算机软件著作权、植物新品种权等知识产权对外转让的，需要按照本办法进行审查。所述知识产权包括其申请权。</span></span></p><p style="text-indent:32px;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（二）本办法所述知识产权对外转让，是指中国单位或者个人将其境',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('96','国家科学技术奖励条例','科技奖励','其他','全国（000000 QG）','中华人民共和国国务院令第731号','国务院令（行政法规）','国务院','2020-12-01','2022-06-21','2020-12-01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（</span><span style="font-family:楷体_GB2312">1999年5月23日中华人民共和国国务院令第265号发布 根据2003年12月20日《国务院关于修改〈国家科学技术奖励条例〉的决定》第一次修订 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第二次修订 2020年10月7日中华人民共和国国务院令第731号第三次修订）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">　　</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">第一章</span> <span style="font-family:宋体">总</span></span></strong><strong><span style="font-family: 宋体;font-size:16px">&nbsp;&nbsp;</span></strong><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">则</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">第一条</span></span></strong><span style=";font-family:宋体;font-size:16px">&nbsp;<span style="font-family:宋体">为了奖励在科学技术进步活动中做出突出贡献的个人、组织，调动科学技术工作者的积极性和创造性，建设创新型国家和世界科技强国，根据《中华人民共和国科学技术进步法》，制定本条例。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">第二条</span></span></strong><span style=";font-family:宋体;font-size:16px">&nbsp;<span style="font-family:宋体">国务院设立下列国家科学技术奖：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（一）国家最高科学技术奖；</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（二）国家自然科学奖；</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（三）国家技术发明奖；</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（四）国家科学技术进步奖；</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（五）中华人民共和国国际科学技术合作奖。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('97','国务院办公厅 印发关于深化科技奖励制度改革方案的通知','科技奖励','其他','全国（000000 QG）','国办函〔2017〕55号','国务院令（行政法规）','国务院办公厅','2017-05-31','2022-06-21','2017-05-31',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-bottom:0;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市人民政府，国务院有关部门：</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">《关于深化科技奖励制度改革的方案》已经党中央、国务院同意，现印发给你们，请认真贯彻落实。</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">国务院办公厅</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family:宋体">2017年5月31日</span></span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:0;margin-bottom:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件公开发布）</span></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong></p><p style="text-indent:32px;line-height:29px;background:rgb(255,255,255)"><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong></p><p style="line-height:29px;background:rgb(255,255,255)"><strong><span style="font-family: 宋体;font-size:16px"><br/></span></strong></p><p style="line-height:29px;background:rgb(255,255,255)"><strong><span style="font-family: 宋体;font-size:16px">&nbsp;</span></strong></p><p style="text-align:center;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">关于深化科技奖励制度改革的方案</span></span></p><p style="text-align:center;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">国办函〔</span><span style="font-family:楷体_GB2312">2017〕55号</span></span><span style="font-family: 楷体_GB2312;font-size:16px"><br/></span></p><p style="text-indent:32px;line-height:29px;background:rgb(255,',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('99','科技部等六部门印发《关于促进文化和科技深度融合的指导意见》的通知','科学技术普及','其他','全国（000000 QG）','国科发高〔2019〕280号','国务院令（行政法规）','科技部 中央宣传部 中央网信办  财政部 文化和旅游部 广播电视总局','2019-08-13','2022-06-21','2019-08-13',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各省、自治区、直辖市、计划单列市科技厅（委、局）、党委宣传部、网信办、财政厅（局）、文化和旅游厅（局）、广播电视局</span><span style="font-family:Calibri">,</span><span style="font-family:宋体">新疆生产建设兵团科技局、党委宣传部、网信办、财政局、文化体育新闻出版广电局：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为促进文化和科技深度融合，全面提升文化科技创新能力，转变文化发展方式，推动文化事业和文化产业更好更快发展，更好满足人民精神文化生活新期待，增强人民群众的获得感和幸福感，科技部、中央宣传部、中央网信办、财政部、文化和旅游部、广播电视总局共同研究制定了《关于促进文化和科技深度融合的指导意见》。现印发给你们，请认真贯彻执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">科技部</span> <span style="font-family:宋体">中央宣传部</span> <span style="font-family:宋体">中央网信办</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">财政部</span> <span style="font-family:宋体">文化和旅游部</span> <span style="font-family:宋体">广播电视总局</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:Calibri">2019</span><span style="font-family:宋体">年</span><span style="font-family:Calibri">8</span><span style="font-family:宋体">月</span><span style="font-family:Calibri">13</span><span style="font-family:宋体">日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件主动公开）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">关于促进文化和科技深度融合的指导意见</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">党的十八大以来，以习近平同志为核心的党中央高度重视文化和科技融合工作，对宣传思想文化战线如何应对新一轮科技革命作出了一系列战略部署，特别是对全媒体时代的媒体融合发展提出了明确要求。目前，国家对网络强国建设作出总体部署，对数字经济发展提出明确要求，有关互联网发展及数字化、网络化、智能化建设正在积极有序推进。同时要看到，文化和科技深度融合仍面临许多新的挑战，科技对文化建设支撑作用的潜力还没有充分释放，相关部门和地方对文化和科技融合的重要性和紧迫性的认识尚需进一步提高，现就促进文化和科技深度融合，提出以下指导意见。</span></span></p><p style="text',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('100','中共河北省委办公厅 河北省人民政府办公厅印发《关于加快实施科技强省行动的实施意见》的通知','综合','其他','河北省（130000 HE）','冀办[2021]18号','国务院令（行政法规）','中共河北省委办公厅 河北省人民政府办公厅','2021-07-16','2022-06-21','2021-07-16',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<h1><br></h1><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span><font face="宋体">各市</font><font face="宋体">(含定州、辛集市)党委和人民政府，雄安新区党工委和管委会，省直各部门，各人民团体:</font></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span><font face="宋体">《关于加快实施科技强省行动的实施意见》已经省委、省政府同意，现印发给你们，请结合实际认真贯彻落实</font><font face="宋体">.</font></span><span><o:p></o:p></span></p><p class="MsoNormal"><span>&nbsp;</span></p><p class="MsoNormal"><span>&nbsp;</span></p><p class="p" align="right" style="text-align: right;"><span>中共河北省委办公厅</span><span><o:p></o:p></span></p><p class="p" align="right" style="text-align: right;"><span>河北省人民政府办公厅</span><span><o:p></o:p></span></p><p class="p" align="right" style="text-align: right;"><span>2021年7月16日</span><span><o:p></o:p></span></p><p class="MsoNormal"><span>&nbsp;</span></p><p class="MsoNormal"><span>&nbsp;</span></p><p class="MsoNormal" align="center" style="text-align: center;"><span>关于加快实施科技强省行动的实施意见</span><span><o:p></o:p></span></p><p class="MsoNormal"><span>&nbsp;</span></p><p class="MsoNormal"><span>为深入实施创新驱动发展战略，以科技创新催生新发展动能，加快建设科技强省，现结合实际提出如下实施意见</span><span>。</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>一、总体要求</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>(一)指导思想</span><span><font face="宋体">。以习新时代中国特色社会主义思想为指导，深入学习贯彻习总书记关于科技创新的重要论述，全面落实党的十九大和十九届二中、三中、四中、五中全会精神，坚持创新在我国现代化建设全局中的核心地位，把提升重点产业链竞争力作为科技强省建设的主攻方向，着力推动创新链与产业链、供应链融合发展，努力实现从科技强到产业强、经济强、河北强的重大转变</font><font face="宋体">.</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>(二)基本原则。</span><span><font face="宋体">坚持目标导向</font><font face="宋体">.以增强产业创新能力为目标，聚焦关键短板和“卡脖子”问题，围绕产业链部署创新链，推动传统产业向高端迈进，提升战略性新兴产业竞争力，打造未来产业发展新优势。</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span><font face="宋体">坚持融通发展</font><font face="宋体">.发挥集中力量办大事的制度优势，统筹优化创新资源配置，加快构建产学研用深度融合的技术创新体系，大力推动创新链各环节融通发展，引领带动产业链提质、供应链优化。</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span><font face="宋体">坚持超前布局</font><font face="宋体">.瞄准重点产业链高质量发展的技术缺失和发展趋势，加大基础研究支持力度，超前布局前沿领域创新平台和研发任务，增强创新驱动源头供给，加快培育产业技术先发优势。</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span><font face="宋体">坚持改革创新</font><font face="宋体">.面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，加快职能转变，增强科技创新协同治理能力，充分激发科技人员和创新主体积极性。</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>(三)工作目标。</span><span>2025年到年，创新型河北建设取得重大突破，研究与试验发展经费年均增长10%以上，研发费用占国内生产总值比重有较大幅度提升，技术合同成交额达到2000亿元，省级以上创新平台达到1500家，科技领军企业、高新技术企业和科技型中小企业数量分别达到100家、1.5万家、10万家，高新技术产业增加值占规模以上工业增加值比重达到25%左右，攻克一批关键核心技术，推动产业基础高级化、产业链现代化建设取得明显成效。</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>二、实施关键核心技术攻关工',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('101','中共河北省委办公厅 河北省人民政府办公厅 印发《关于大力推进科技创新工作的若干措施》的通知','综合','其他','河北省（130000 HE）','冀办〔2021 ]28号','国务院令（行政法规）','中共河北省委办公厅 河北省人民政府办公厅','2021-11-15','2022-06-21','2021-11-15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<h1><span style="text-align: justify; font-size:16px; font-weight: normal;">各市（含定州、辛集市）、县（市、区）党委和人民政府，雄安新区党工委和管委会，省直各部门，各人民团体：</span></h1><p class="MsoNormal" align="justify" style="text-align: justify;"><span>《关于大力推进科技创新工作的若干措施》已经省委、省政府同意，现印发给你们，请结合实际认真贯彻落实。</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span></p><p class="p" align="right" style="text-align: right;"><span>中共河北省委办公厅</span><span><o:p></o:p></span></p><p class="p" align="right" style="text-align: right;"><span>河北省人民政府办公厅</span><span><o:p></o:p></span></p><p class="p" align="right" style="text-align: right;"><span>2021年11月15日</span><span><o:p></o:p></span></p><p class="p"><span>（此件公开发布，责任分工不公开）</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span></p><p class="MsoNormal" align="center" style="text-align: center;"><span>关于大力推进科技创新工作的若干措施</span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>&nbsp;</span></p><p class="p" align="justify" style="text-align: justify;"><span><font face="宋体">为认真贯彻落实习近平总书记关于科技创新的重要论述和对河北工作的重要指示精神，深入实施创新驱动发展战略，加快提升全省科技创新水平，为新时代全面建设经济强省、美丽河北提供强有力支撑，结合实际制定如下措施。</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>一、加快提高全社会研发投入水平</span><span><o:p></o:p></span></p><p class="p" align="justify" style="text-align: justify;"><span>（一）激励各地加大研发投入。</span><span><font face="宋体">持续加大对设区市研发投入增长的奖励力度，</font><font face="宋体">“十四五”期间，对研究与试验发展经费投入强度高于年的设区市，每增加0.01个百分点，奖励100万元；对研发投入强度超过全国平均水平的设区市给予一次性5000万元奖励，用于推动科技创新活动。（责任单位：省科技厅、省财政厅）</font></span><span><o:p></o:p></span></p><p class="p" align="justify" style="text-align: justify;"><span>（二）引导企业加大研发投入。</span><span><font face="宋体">“十四五”期间，推行企业研发投入后补助制度，对享受研发费用加计扣除政策优惠的科技型企业，省财政按照企业上一年度享受优惠的实际研 发投入新增部分的10%予以补助，单个企业年度最高补助1000万元。对新获批国家级创新平台的企业给予资金支持，用于自主科研开发、合作研发、成果转化、科研仪器设备更新改造等。（责任单位</font></span><span><font face="宋体">:</font></span><span><font face="宋体">省财政厅、省科技厅、省税务局、省发展改革委）</font></span><span><o:p></o:p></span></p><p class="p" align="justify" style="text-align: justify;"><span>（三）推动国有企业加大研发投入</span><span><font face="宋体">。建立国有企业研发投入刚性增长机制和省属重点工业企业科技投入通报制度落实和完善国有企业研发投入视同利润的考核措施。鼓励支持国有企业建立创新平台，到</font><font face="宋体">2025年，实现国有规模以上工业企业研发机构全覆盖。（责任单位：省国资委、省科技厅、省发展改革委）</font></span><span><o:p></o:p></span></p><p class="p" align="justify" style="text-align: justify;"><span>（四）支持高校院所加大研发投入。</span><span><font face="宋体">进一步加大对高校院所科技经费支持力度，引导增加基础研究投入、深化产学研结合等。建立研发投入通报制度，将研发投入纳入省属重点骨干高校、省属科研院所创新资源配置、绩效考核评价指标体系。（责任单位：省教育厅、省科技厅）</font></span><span><o:p></o:p></span></p><p class="MsoNormal" align="justify" style="text-align: justify;"><span>二、加快建立科技人才资源竞争优势</span><span><o:p></o:p></span></p><p class="p" align="justify" style="',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('102','中共河北省委  河北省人民政府 关于加快科技创新建设创新型河北的决定','综合','其他','河北省（130000 HE）','冀发〔2016〕29号','国务院令（行政法规）','中共河北省委  河北省人民政府','2016-07-10','2022-06-21','2016-07-10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深入贯彻全国科技创新大会精神，全面落实《国家创新驱动发展战略纲要》，推动以科技创新为核心的全面创新，加快建设创新型河北，现作出如下决定。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">一、总体要求</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（一）重大意义。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">创新始终是推动一个国家、一个民族向前发展的重要力量。新一轮科技革命和产业变革正在孕育兴起和交互影响，国际经济竞争更加突出地体现为科技创新的竞争。我国经济发展进入新常态，依靠要素驱动和资源消耗支撑的发展方式难以为继，面临着动力转换、方式转变、结构调整的繁重任务。以习近平同志为总书记的党中央提出了建设世界科技强国的战略目标，明确了推进以科技创新为核心的全面创新的总体要求。当前，河北正处于转型升级、爬坡过坎、跨越赶超的关键时期，加快补齐科技创新和信息化短板，通过科技创新培育新动能、打造新优势、实现新发展已迫在眉睫。推进科技创新、建设创新型河北，是全面贯彻创新、协调、绿色、开放、共享发展理念，实施创新驱动发展战略的重大抉择；是落实</span><span style="font-family:宋体">“协同发展、转型升级、又好又快”工作主基调的战略举措；是加强科技供给、推进供给侧结构性改革的紧迫任务；是决胜“十三五”、全面建成小康社会的强大支撑。全省上下必须把科技创新摆在更加突出的位置，切实增强忧患意识和使命意识，以强烈的责任感和紧迫感，坚定不移地走好创新驱动发展之路。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（二）指导思想。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">全面贯彻党的十八大和十八届三中、四中、五中全会精神，深入贯彻习近平总书记系列重要讲话和对河北的重要指示精神，全面落实《国家创新驱动发展战略纲要》，紧紧抓住京津冀协同发展的重大机遇，围绕建设创新型河北的总目标，树立和践行新发展理念，以科技创新为核心带动全面创新，以产业创新为重点带动转型升级，以京津冀协同创新为引领带动区域创新，以体制机制创新为保障激发全社会创新活力，更加注重发挥</span><span style="font-family:宋体">“科技第一生产力、创新第一动力、人才第一资源”的基础性作用，更加注重发挥科技创新在供给侧结构性改革中的关键性作用，更加注重发挥市场对各类创新要素配置的决定性作用，更加注重发挥“大智移云”在重构现代产业体系中的战略性作用，全力打造经济社会发展的新动能、新引擎，为建设经济强省、美丽河北提供强大动力。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:楷体_GB2312;font-size:16px"><span style="font-family:楷体_GB2312">（三）奋斗目标。</span></span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">到</span><span style="font-family:宋体">2018年，创新型河北建设迈出重要步伐。突破一批重大产业关键技术，培育一批10亿级创新型企业、百亿级创新型产业集群、千亿级创新型园区，形成一批具有核心竞争力的自主创新品牌。以“大智移云”为核心的新一代信息产业实现快速发展，传统产业技术水平大幅提高，先进制造业与战略性新兴产业增加值占比较快提升，科技进步贡献率达到55%左右，综合科技进步水平进入全国18名以内，为建设创新型河北奠定重要基础。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">到</span><span style="font-family:宋体">2020年，创新型河北建设跃上新台阶。适应市场经济要求、符合科技创新规律、充满活力和富有效率的体制机制基本建立，具有河北特色的区域创新体系基本形成，创新生态更加优化，创新资源有效聚集，创新能力显著增强，实现“三个提升、两个突破、一个确保”的奋斗目标。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">“三个提升”：企业创新能力大幅提升，科技型中小企业达到8万家，高新技术企业力争达到4000家；产业创新能力大幅提升，高新技术产业增加值占规模以上工业增加值比重达到25%以上，以“大智移云”为核心的新一代信息技术产业规模突破3000亿元；区域创新能力大幅提升，全社会R&amp;D经费支出占GDP比重达到2.5%，万人发明专利拥有量达到8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('181','中共河北省委办公厅 河北省人民政府办公厅印发《关于深化项目评审、人才评价、机构评估改革的实施意见》的通知','科技条件与标准','其他','河北省（130000 HE）','冀办发〔2019〕1号','国务院令（行政法规）','中共河北省委办公厅 河北省人民政府办公厅','2019-01-05','2022-06-22','2019-01-05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各市（含定州、辛集市）、县（市、区）党委和人民政府，雄安新区党工委和管委会，省直各部门，各人民团体：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">《关于深化项目评审、人才评价、机构评估改革的实施意见》已经省委、省政府领导同意，现印发给你们，请结合实际认真贯彻落实。</span></span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">中共河北省委办公厅</span></span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省人民政府办公厅</span></span></p><p style="text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2019年1月5日</span></span></p><p><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-left:0;text-indent:0;text-align:justify;text-justify:inter-ideograph"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件公开发布）</span></span></p><p><span style="font-family: 宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;line-height:29px"><span style="font-family: 宋体;font-size:16px">&nbsp;</span></p><p style="margin-left:0;text-indent:0;text-align:center"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">关于深化项目评审、人才评价、机构评估改革的意见</span></span></p><p style=";text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style="font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为贯彻落实中共中央办公厅、国务院办公厅印发的《关于深化项目评审、人才评价、机构评估改革的意见》，深入推进科技评价制度改革，完善科技评价体系</span><span style="font-family:宋体">,释放创新创业活力,结合我省实际，提出以下实施意见。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">一、总体思路</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，深入实施创新驱动发展战略，落实党中央、国务院深化科技体制改革的决策部署，以改革项目评审、人才评价、机构评估（以下简称</span><span style="font-family:宋体">“三评”）为关键，以调动科技人员积极性创造性为核心，统筹自然科学和哲学社会科学等不同学科门类，按照“尊重规律、问题导向、分类评价、客观公正”的原则，优化科研项目评审管理、改进科技人才评价方式、完善科研机构评估制度，精简“三评”项目',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('182','河北省科学技术厅 关于印发《河北省科技创新政策落实评估工作指引 (试行)》的通知','科技条件与标准','其他','河北省（130000 HE）','冀科政函〔2017〕144号','国务院令（行政法规）','河北省科学技术厅','2017-11-11','2022-06-22','2017-11-11',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:0;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各市（含定州、辛集市）科技局，省级以上高新区管委会：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">党的十八大以来，党中央国务院和省委省政府出台了一系列深入实施创新驱动发展战略、推进科技体制改革创新的政策文件。为全面提升执行力，促进科技创新政策落实落地，省科技厅制定了《河北省科技创新政策落实评估工作指引（试行）》，明确了评估指标体系、评估程序、评估重点等内容，是完善科技创新政策支撑体系的规范性文件。在做好近几年重大创新政策落实情况评估的基础上，以后凡是省级出台的科技创新政策均按照时间节点和有关要求开展评估。请你们对省级层面开展的科技创新政策落实评估工作积极配合，并结合本地情况加强科技创新政策落实情况评估工作，有关评估工作和程序要求可参照本《指引》。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">附件：河北省科技创新政策落实评估工作指引（试行）</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省科学技术厅</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2017年11月11日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">（此件依申请公开）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:0;text-align:center;line-height:29px"><strong><span style="font-family: 宋体;font-size:16px"><span style="font-family:宋体">河北省科技创新政策落实评估工作指引（试行）</span></span></strong></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">第一条</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;<span style="font-family:宋体">为完善科技创新政策支撑体系，全面加强科技创新政策评估工作，建立科技创新政策规范化、制度化评估体系和工作机制，推动科技创新政策有效落实，特制定本工作指引。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">第二条</span></span><span style',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('200','河北省科学技术厅关于印发 《河北省科普示范基地管理办法（试行）》的通知','科学技术普及','其他','河北省（130000 HE）','冀科政规〔2019〕1号','国务院令（行政法规）','河北省科学技术厅','2019-05-14','2022-06-22','2019-05-14',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:0;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各市（含定州、辛集市）科技局、雄安新区管委会改革发展局，省科普工作联席会议成员单位，有关单位：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为加强全省科普能力建设，充分发挥科普基地的示范引领作用，省科技厅研究制定了《河北省科普示范基地管理办法（试行）》，现予以印发。请结合实际，认真抓好实施。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">省级科普示范基地认定工作将于近期开展，请各地各单位积极做好相关准备工作，具体时间另行通知。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">咨询电话：</span><span style="font-family:宋体">85817982</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">85803093</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-top:15px;margin-right:0;margin-bottom:0;margin-left:0;text-indent:0;padding:0 0 0 0 ;text-align:right;background:rgb(255,255,255)"><span style="font-family: 宋体;color: rgb(102, 102, 102);letter-spacing: 0;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省科学技术厅</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2019年5月14日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p><span style="font-family:宋体;color: rgb(51, 51, 51);letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">&nbsp;</span></p><p style="text-indent:0;text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">河北省科普示范基地管理办法（试行）</span></span></p><p style="text-indent:0;text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px">&nbsp;</span></p><p style="text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">第一章</span></span><span style=";font-family:黑体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">总</span></span><span style=";font-family:黑体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">则</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-he',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('201','河北省科学技术厅 关于印发《河北省国际科技合作基地管理办法》的通知','国际科技合作','其他','河北省（130000 HE）','冀科外〔2019〕10号','国务院令（行政法规）','河北省科学技术厅','2019-05-28','2022-06-22','2019-05-28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:0;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各市（含定州、辛集市）科技局、雄安新区管委会改革发展局，各国家级高新区管委会，省直有关部门：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深入贯彻落实</span><span style="font-family:宋体">“一带一路”重大战略部署和《中共河北省委、河北省人民政府关于进一步推进新时代对外开放的意见》，进一步提升我省国际科技合作条件和能力建设，深化国际科技交流与合作，规范河北省国际科技合作基地的建设工作，我们对《河北省国际科技合作基地管理办法》（冀科外〔2013〕4号）进行了修订。现将修订后的《河北省国际科技合作基地管理办法》印发给你们，请遵照执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省科学技术厅</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2019年5月28日</span></span></p><p><span style="font-family:宋体;color: rgb(51, 51, 51);letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">&nbsp;</span></p><p><span style="font-family:宋体;color: rgb(51, 51, 51);letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">&nbsp;</span></p><p style="text-indent:0;text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">河北省国际科技合作基地管理办法</span></span></p><p style="text-indent:0;text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px">&nbsp;</span></p><p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">第一章</span> </span><span style="font-family: 黑体;font-size:16px">&nbsp;</span><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">总</span> </span><span style="font-family: 黑体;font-size:16px">&nbsp;</span><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">则</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 黑体;font-size:16px"><span style="font-family:黑体">第一条</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为深入贯彻落实</span><span style="font-family:宋体">“一带一路”重大战略部署和《中共河北省委、河北省人民政府关于进一步推进新时代对外开放的意见》（冀发〔2018〕18号），进一步深化我省国际科技交流与合作，规范国际科技合作基地的认定和管理，参照《国家国际科技合作基地管理办法》（国科发外〔2011〕316号），结合我省实际，制定本办法。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style="font-family: 黑体;font-size:16px"><span style="font-fami',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('202','河北省科学技术厅 河北省财政厅 关于印发《河北省国际科技合作基地建设补助 资金实施细则（试行）》的通知','国际科技合作','其他','河北省（130000 HE）','冀科外〔2020〕3号','国务院令（行政法规）','河北省科学技术厅 河北省财政厅','2020-09-10','2022-06-22','2020-09-10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="text-indent:0;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">各市（含定州、辛集市）科技局、财政局，雄安新区管委会改革发展局，各国家级高新区管委会，省直有关部门：</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">为促进河北省国际科技合作基地建设和发展，规范河北省国际科技合作基地建设补助资金管理，提高省级财政科技资金使用效益，根据《河北省财政厅</span> <span style="font-family:宋体">河北省科学技术厅</span><span style="font-family:宋体">&lt;关于印发河北省创新能力提升专项资金管理办法（暂行）&gt;的通知》（冀财规〔2019〕4号）等有关规定，我们制定了《河北省国际科技合作基地建设补助资金实施细则（试行）》，现印发给你们，请遵照执行。</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省科学技术厅</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;</span><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">河北省财政厅</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;text-align:right;line-height:29px"><span style=";font-family:宋体;font-size:16px"><span style="font-family:宋体">2020年9月10日</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px;background:rgb(255,255,255)"><span style="font-family: 宋体;font-size:16px">&nbsp;</span></p><p style="text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:&#39;Times New Roman&#39;;font-size:16px">&nbsp;</span></p><p style="text-indent:0;text-align:center;line-height:29px"><span style=";font-family:方正小标宋简体;font-size:16px"><span style="font-family:方正小标宋简体">河北省国际科技合作基地建设补助资金</span><span style="font-family:方正小标宋简体">实施细则（试行）</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:宋体;font-size:16px">&nbsp;</span></p><p style="margin-left:0;text-indent:0;text-autospace:ideograph-numeric;text-align:center;line-height:29px;background:rgb(255,255,255)"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">第一章</span> &nbsp;<span style="font-family:黑体">总</span></span><span style=";font-family:黑体;font-size:16px">&nbsp;&nbsp;</span><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">则</span></span></p><p style="text-indent:32px;text-autospace:ideograph-numeric;line-height:29px"><span style=";font-family:黑体;font-size:16px"><span style="font-family:黑体">第一条</span></span><span style=";font-family:宋体;font-size:16px">&nbsp;&nbsp;<span style="font-family:宋体">为规范河北省国际科技合作基地建设补助资金（以下简称</span><span style="font-family:宋体">“补助资金”）管理，根据《河北省财政厅 河北省科学技术厅&lt;关于印发河北省创新能力提升专项资金管理办法（暂行）&gt;的通知》（冀财规〔2019〕4号），结合工作实际，制定本细则。</span></span></p><p st',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('218','北京市推广应用新能源汽车管理办法','企业技术进步与高新技术产业化','其他','北京市（110000 BJ）','京科发〔2018〕25号','国务院令（行政法规）','北京市科委、市经济信息化委、市财政局、市城市管理委、市交通委','2018-02-24','2022-07-04','2018-02-24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第一条</span> <span style="font-family:宋体">&nbsp;为落实《国务院办公厅关于加快新能源汽车推广应用的指导意见》（国办发〔2014〕35号）、《关于2016-2020年新能源汽车推广应用财政支持政策的通知》（财建〔2015〕134号）等文件要求，贯彻落实国家发展新能源汽车的战略部署，坚持创新、协调、绿色、开放、共享的发展理念，倡导绿色低碳出行，有效推进节能减排，优化配套环境，落实和完善扶持政策，结合本市新能源汽车推广应用实际，制定本办法。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第二条</span> <span style="font-family:宋体">&nbsp;本办法所称新能源汽车是指依法获得许可在中国境内销售的纯电动汽车和燃料电池汽车。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第三条</span> <span style="font-family:宋体">&nbsp;本市鼓励购买和使用新能源汽车，本市相关财政补助政策参照《财政部 工业和信息化部 科技部 发展改革委关于调整完善新能源汽车推广应用财政补贴政策的通知》（财建〔2018〕18号）另行研究制定。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第四条</span> <span style="font-family:宋体">&nbsp;按照《北京市小客车数量调控暂行规定》及其实施细则（2017年修订），本市实施新能源小客车指标管理政策，并通过轮候方式配置，单位或者个人应按照本市新能源小客车指标管理相关规定申请取得和使用。持有普通小客车指标的单位或者个人可购置、登记新能源小客车。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第五条</span> <span style="font-family:宋体">&nbsp;本市各级党政机关、事业单位、国有企业应当带头使用新能源汽车，按照规定逐步扩大新能源汽车配备比例，通过完善充电设施等措施，为本单位职工购买使用新能源汽车提供便利，发挥对社会的示范引领作用。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第六条</span> <span style="font-family:宋体">&nbsp;新能源汽车生产企业是产品安全、质量、售后服务、应急保障以及动力电池回收的责任主体，应切实尽职履责，建立新能源汽车产品质量安全责任制，确保新能源汽车安全运行。生产企业应建立企业监控平台，按照相关要求，及时、准确上报相关信息。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:justify;text-justify:inter-ideograph;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">第七条</span> <span style="font-family:宋体">&nbsp;本市推进适度超前、布局合理、管理规范、智能高效的充电基础设施体系建设，为用户提供',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('219','关于印发《北京市“十三五”时期加快新能源汽车发展的指导意见》的通知（失效）','企业技术进步与高新技术产业化','其他','北京市（110000 BJ）','京科发〔2016〕484号','国务院令（行政法规）','北京市科学技术委员会  北京市发展和改革委员会  北京市经济和信息化委员会  北京市财政局  北京市交通委员会','2016-09-07','2022-07-04','2016-09-07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style="margin: 0 0 20px;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">各相关单位：</span></p><p style="margin: 0 0 20px;text-indent:32px;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">“十三五”时期，为进一步加快推进本市新能源汽车技术创新，打造高精尖的新能源汽车产业，巩固提升新能源汽车推广应用高地，结合本市新能源汽车发展实际情况，我们研究制定了《北京市“十三五”时期加快新能源汽车发展的指导意见》，经报市政府同意，现印发给你们，请遵照执行。</span></p><p style="margin: 0 0 20px;text-indent:32px;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">特此通知。</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">北京市科学技术委员会</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">北京市发展和改革委员会</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">北京市经济和信息化委员会</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">北京市财政局</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">北京市交通委员会</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-indent:32px;text-align:right;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">2016年9月7日</span></p><p style="margin-top:0;margin-right:0;margin-bottom:20px;margin-left:0;text-align:center;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">北京市</span><span style="font-family:宋体">“十三五”时期加快新能源汽车发展的指导意见</span></span></p><p style="margin: 0 0 20px;text-indent:32px;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px"><span style="font-family:宋体">近十年尤其是</span><span style="font-family:宋体">“十二五”以来，本市新能源汽车快速发展，率先跨越市场导入期进入快速成长期，新能源汽车产业生态体系和配套政策体系基本建立。“十三五”时期，是本市新能源汽车规模化普及应用的关键期，为贯彻落实国家《节能与新能源汽车产业发展规划（2012—2020年）》（国发〔2012〕22号）、《关于加快新能源汽车推广应用的指导意见》（国办发〔2014〕35号）、《关于加快电动汽车充电基础设施建设的指导意见》（国办发〔2015〕73号）等政策精神，加快推进本市新能源汽车技术创新、构建高精尖的新能源汽车产业、打造新能源汽车推广应用高地，现提出以下指导意见。</span></span></p><p style="margin: 0 0 20px;text-indent:32px;line-height:29px"><span style="font-family:宋体;color: rgb(61, 61, 61);letter-spacing: 0;font-size:16px">一、总体要求</span></p><p style="margin: 0 0 20px;text-indent:32px;line-height:29px"><sp',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO policy (id,name,type,category,`range`,document,form,organ,viadata,pubdata,perdata,field,theme,keyword,superior,precursor,succeed,state,text,pdf,redundancy,`rank`,policykey,newrank,`year`,newkey,secondtheme,allsum) VALUES ('261','广东省自主创新促进条例',NULL,'其他','广东省（440000 GD）','广东省第十三届人民代表大会常务委员会 公 告 （第46号）','国务院令（行政法规）','广东省人民代表大会常务委员会','2019-09-25','2022-07-04','2019-09-25',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p style=";padding: 0"><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">《广东省自主创新促进条例》已由广东省第十三届人民代表大会常务委员会第十四次会议于</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">2019</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">年</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">9</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">月</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">25</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">日修订通过，现将修订后的《广东省自主创新促进条例》公布，自</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">2019</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">年</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">12</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">月</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">1</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">日起施行。</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-align:right"><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">广东省人民代表大会常务委员会</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-align:right"><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">2019</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">年</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">9</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">月</span></span><span style="font-family: Arial;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">25</span><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)"><span style="font-family:宋体">日</span></span></p><p style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding:0 0 0 0 ;text-align:center"><span style="font-family:宋体;letter-spacing: 0;font-size:16px;background: rgb(255, 255, 255)">　　</span><stro',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
